import{n as i}from"./shared-CAKwAg2C.js";const a={"LEARN HOW THE INTERNET WORKS":"SO FUNKTIONIERT DAS INTERNET","NOW LEARNING":"AKTUELLE LEKTION","OSI LAYER":"OSI-SCHICHT","LEARNING PROGRESS":"DEIN FORTSCHRITT",COMPLETE:"FERTIG","IN PROGRESS":"IN ARBEIT","{pct}% complete":"{pct} % abgeschlossen","DESIGNED BY":"GESTALTET VON","Dilum Sanjaya on X":"Dilum Sanjaya auf X","Layer {n}: {name}":"Schicht {n}: {name}",Physical:"Bitübertragung","Data Link":"Sicherung",Network:"Vermittlung",Transport:"Transport",Session:"Sitzung",Presentation:"Darstellung",Application:"Anwendung","OVERVIEW · {n} STEPS":"ÜBERSICHT · {n} SCHRITTE","STEP {n}/{total} · {title}":"SCHRITT {n}/{total} · {title}","LESSON COMPLETE":"LEKTION ABGESCHLOSSEN",PROTOCOLS:"PROTOKOLLE",Protocols:"Protokolle",Language:"Sprache",Theme:"Design","Light mode":"Heller Modus","Dark mode":"Dunkler Modus","INTERNET PROTOCOLS":"INTERNETPROTOKOLLE",More:"Mehr","Close the protocol list":"Protokollliste schließen","Close (Esc)":"Schließen (Esc)",ALL:"ALLE",CORE:"BASIS",APPLICATION:"ANWENDUNG",SECURITY:"SICHERHEIT",NETWORK:"NETZWERK",SEQUENCE:"SEQUENZ",View:"Ansicht","Switch view (V)":"Ansicht wechseln (V)","Network diagram":"Netzwerkdiagramm","Sequence diagram":"Sequenzdiagramm","STEP {n}":"SCHRITT {n}","PROTOCOL OVERVIEW":"ÜBERSICHT","STEP DETAILS":"SCHRITTDETAILS","LESSON SUMMARY":"ZUSAMMENFASSUNG",OVERVIEW:"START",ACTIVE:"AKTIV","STEP {n} OF {total}":"SCHRITT {n} VON {total}","PACKET {n} OF {total}":"PAKET {n} VON {total}","PACKETS {from}–{to} OF {total}":"PAKETE {from}–{to} VON {total}","{n} LOST":"{n} VERLOREN","1 LOST":"1 VERLOREN",ENCRYPTED:"VERSCHLÜSSELT","LOST ON THE WAY":"UNTERWEGS VERLOREN","PACKET FLOW":"PAKETFLUSS","Colour key":"Farblegende","Playback speed":"Wiedergabegeschwindigkeit","Previous step (←)":"Vorheriger Schritt (←)","Previous step":"Vorheriger Schritt","Play / pause (Space)":"Abspielen / Pause (Leertaste)",PLAY:"ABSPIELEN",PAUSE:"PAUSE",REPLAY:"NOCHMAL",STEP:"SCHRITT","One packet at a time":"Ein Paket nach dem anderen",RESET:"ZURÜCKSETZEN",Reset:"Zurücksetzen","Back to the overview (Esc)":"Zurück zur Übersicht (Esc)","NO.":"NR.",TIME:"ZEIT",SOURCE:"QUELLE",DESTINATION:"ZIEL",PROTOCOL:"PROTOKOLL",INFO:"INFO",SIZE:"GRÖSSE","No packets on the wire yet.":"Noch keine Pakete unterwegs.",LOST:"VERLOREN","Packet inspector":"Paketinspektor","Previous packet":"Vorheriges Paket","Previous packet (←)":"Vorheriges Paket (←)","Next packet":"Nächstes Paket","Next packet (→)":"Nächstes Paket (→)",Close:"Schließen","E.G.":"BSP.","an example value: it differs in every real capture":"ein Beispielwert: in jeder echten Aufzeichnung anders","bytes the lesson can’t show: encrypted, random, or a file’s contents":"Bytes, die die Lektion nicht zeigen kann: verschlüsselt, zufällig oder der Inhalt einer Datei",BYTES:"BYTES","{n} in this frame":"{n} in diesem Frame","This row stands for {n} TCP segments carrying a {size}-byte message; the first segment is shown":"Diese Zeile steht für {n} TCP-Segmente mit einer Nachricht von {size} Bytes; gezeigt wird das erste Segment","This packet was lost on the way":"Dieses Paket ging unterwegs verloren",Padding:"Auffüllung","192.168.1.10/24 · 24 H LEASE":"192.168.1.10/24 · LEASE 24 H","2 SEGMENTS":"2 SEGMENTE","3 SEGMENTS":"3 SEGMENTE","3 DATAGRAMS":"3 DATAGRAMME","4 DATAGRAMS":"4 DATAGRAMME","203.0.113.10 IS NOT LOCAL":"203.0.113.10 IST NICHT LOKAL","250 QUEUED":"250 IN WARTESCHLANGE",ANSWER:"ANTWORT","APP COVERS THE 20 MS GAP":"APP ÜBERBRÜCKT DIE 20-MS-LÜCKE","APP DATA":"APP-DATEN","ARP REPLY":"ARP-ANTWORT","ARP REQUEST":"ARP-ANFRAGE","ARRIVED WITH TTL 116":"ANGEKOMMEN MIT TTL 116","AUTH FAILURE":"AUTH FEHLGESCHLAGEN","At QUIT":"Bei QUIT","CACHED · TTL 3600 S":"IM CACHE · TTL 3600 S","CERTIFICATE VALID":"ZERTIFIKAT GÜLTIG","CHAIN LEADS TO A TRUSTED ROOT":"KETTE FÜHRT ZU EINER VERTRAUTEN ROOT","CHANNEL OPEN":"KANAL ÖFFNEN",CONFIRMED:"BESTÄTIGT","DNS QUERY":"DNS-ANFRAGE","DNS REPLY":"DNS-ANTWORT","DUP ACK":"DOPPEL-ACK","EACH KEY IS ITS OWN PACKET":"JEDE TASTE EIN EIGENES PAKET",ECHO:"ECHO","ECHO REPLY":"ECHO-ANTWORT","ECHO REQUEST":"ECHO-ANFRAGE",ENTER:"EINGABE","FRAME 7 LOST · NOT RESENT":"FRAME 7 VERLOREN · NICHT ERNEUT GESENDET","HOP 2 · 198.51.100.1":"HOP 2 · 198.51.100.1","HOST KEY MATCHES KNOWN_HOSTS":"HOST-SCHLÜSSEL PASST ZU KNOWN_HOSTS","IN BOB’S MAILBOX":"IN BOBS POSTFACH","IP PACKET":"IP-PAKET",MESSAGE:"NACHRICHT","MESSAGE 1 DELETED":"NACHRICHT 1 GELÖSCHT","NEW MAIL ARRIVED":"NEUE MAIL EINGETROFFEN","NO IP ADDRESS YET":"NOCH KEINE IP-ADRESSE","NOT IN CACHE":"NICHT IM CACHE","OFFER KEY":"SCHLÜSSEL ANBIETEN",OUTPUT:"AUSGABE","PASSWORD IN PLAIN TEXT":"PASSWORT IM KLARTEXT",REFERRAL:"VERWEIS",REPLY:"ANTWORT",RESEND:"ERNEUT SENDEN","SEGMENT 1 LOST":"SEGMENT 1 VERLOREN","SFTP or FTPS":"SFTP oder FTPS","SFTP, or FTPS (FTP + TLS)":"SFTP oder FTPS (FTP + TLS)","SHARED SECRET COMPUTED":"GEMEINSAMES GEHEIMNIS BERECHNET",SIGNED:"SIGNIERT","STILL ON SERVER · \\SEEN":"NOCH AUF DEM SERVER · \\SEEN",SUCCESS:"ERFOLG","TIME EXCEEDED":"ZEIT ÜBERSCHRITTEN","TIME=34MS TTL=52":"ZEIT=34MS TTL=52",UNREACHABLE:"UNERREICHBAR",VERSION:"VERSION","VOICE 1":"STIMME 1","+OK or -ERR":"+OK oder -ERR",".com Server":".com-Server",Authoritative:"Autoritativ","Log In":"Anmelden",Key:"Schlüssel",Why:"Warum",End:"Ende","MACs, in":"MACs, eingehend",Internet:"Internet",Router:"Router","Router 192.168.1.1":"Router 192.168.1.1","Router: 192.168.1.1":"Router: 192.168.1.1",Routers:"Router",Hardware:"Hardware",Audio:"Audio",Ping:"Ping",Cookie:"Cookie","Magic cookie":"Magic Cookie",Visible:"Sichtbar",Tickets:"Tickets","4, 20 bytes":"4, 20 Bytes","20–60 bytes":"20–60 Bytes","20–60 bytes (IPv4)":"20–60 Bytes (IPv4)","8 bytes (TCP: 20+)":"8 Bytes (TCP: 20+)","32 bytes (Windows)":"32 Bytes (Windows)","1,460 bytes (MSS)":"1,460 Bytes (MSS)","78 bytes (seq 1–78)":"78 Bytes (seq 1–78)","bytes 1461–2920":"Bytes 1461–2920","text/html, 12.2 KB":"text/html, 12.2 KB","1026 (× 256 = 262,656 bytes)":"1026 (× 256 = 262,656 Bytes)","501 (× 128 = 64,128 bytes)":"501 (× 128 = 64,128 Bytes)","X25519MLKEM768 (1,216 bytes), X25519":"X25519MLKEM768 (1,216 Bytes), X25519","X25519MLKEM768 (1,120 bytes)":"X25519MLKEM768 (1,120 Bytes)",'"abcdefghijklmnopqrstuvwabcdefghi" (32 bytes)':'"abcdefghijklmnopqrstuvwabcdefghi" (32 Bytes)','"hello, anyone here" (18 bytes)':'"hello, anyone here" (18 Bytes)',"32 bits (IPv4), 128 (IPv6)":"32 Bit (IPv4), 128 (IPv6)","64 → 52 (12 routers)":"64 → 52 (12 Router)","52 (64 − 12 routers)":"52 (64 − 12 Router)","1 (Ethernet)":"1 (Ethernet)","report.pdf, 4,000 bytes":"report.pdf, 4,000 Bytes","1190 bytes (sntrup761 1,158 + X25519 32)":"1190 Bytes (sntrup761 1,158 + X25519 32)","RTP + audio":"RTP + Audio"},o={"Hypertext Transfer Protocol":"Hypertext-Übertragung","HTTP Secure":"Sicheres HTTP","Transmission Control Protocol":"Übertragungssteuerung","User Datagram Protocol":"Benutzer-Datagramme","Internet Protocol":"Internetprotokoll","Domain Name System":"Domain-Namenssystem","Dynamic Host Configuration":"Dynamische Host-Konfiguration","Internet Control Message":"Internet-Steuernachrichten","Simple Mail Transfer Protocol":"Einfacher Mailtransfer","Post Office Protocol v3":"Post Office Protocol v3","Internet Message Access":"Internet-Nachrichtenzugriff","File Transfer Protocol":"Dateiübertragung","Secure Shell":"Sichere Shell","Transport Layer Security":"Transportschicht-Sicherheit",Internet:"Internet",Client:"Client",Router:"Router","DNS Resolver":"DNS-Resolver","Web Server":"Webserver","Root Server":"Root-Server",".com TLD Server":".com-TLD-Server","Authoritative Server":"Autoritativer Server","Mail Server":"Mailserver","Web Communication":"Webkommunikation",Request:"Anfrage",Response:"Antwort","Data ACKs not shown":"Daten-ACKs nicht gezeigt","HTTP is the protocol of the web: a client asks for a resource, such as an HTML page, and the server answers with a status code, headers and usually a body. Every exchange is one request and one response, written as readable text in HTTP/1.1.":"HTTP ist das Protokoll des Webs: Ein Client fragt eine Ressource an, etwa eine HTML-Seite, und der Server antwortet mit einem Statuscode, Headern und meist einem Body. Jeder Austausch besteht aus einer Anfrage und einer Antwort, in HTTP/1.1 als lesbarer Text geschrieben.",Layer:"Schicht","Application (Layer 7)":"Anwendung (Schicht 7)","Default Port":"Standardport",Transport:"Transport","Data Format":"Datenformat","Text (headers + optional body)":"Text (Header + optionaler Body)","Common Methods":"Häufige Methoden","Defined In":"Definiert in","Page delivered":"Seite ausgeliefert","One request, one response":"Eine Anfrage, eine Antwort","In under a tenth of a second the laptop looked up an address, opened a TCP connection and exchanged one HTTP request and response, all of it readable by anyone on the path. Press REPLAY to watch it again.":"In weniger als einer Zehntelsekunde hat der Laptop eine Adresse nachgeschlagen, eine TCP-Verbindung geöffnet und eine HTTP-Anfrage und -Antwort ausgetauscht, alles für jeden auf dem Weg lesbar. Drücke NOCHMAL, um es dir noch einmal anzusehen.","Round trips":"Round Trips","Total time":"Gesamtzeit","Page size":"Seitengröße","Sent as 9 TCP segments":"In 9 TCP-Segmenten gesendet","Client Request":"Anfrage des Clients","Browser prepares the request":"Der Browser bereitet die Anfrage vor","You open http://www.example.com. The browser will send a GET request, but packets travel to IP addresses, not names, so first it needs the server’s address. (Browsers now try https:// first; this is the plain version.)":"Du öffnest http://www.example.com. Der Browser wird eine GET-Anfrage senden, aber Pakete reisen zu IP-Adressen, nicht zu Namen, also braucht er zuerst die Adresse des Servers. (Browser versuchen heute zuerst https://; dies ist die unverschlüsselte Variante.)",Method:"Methode","Next hop":"Nächster Hop","Router 192.168.1.1":"Router 192.168.1.1","DNS Resolution":"DNS-Auflösung","Finds the server’s IP address":"Findet die IP-Adresse des Servers","The laptop asks the DNS server it was given by DHCP, 8.8.8.8, for the address of www.example.com. The query goes over UDP port 53 and the answer is an A record with the IPv4 address. (On a network with IPv6 it would also ask for an AAAA record.)":"Der Laptop fragt den DNS-Server, den er per DHCP bekommen hat, 8.8.8.8, nach der Adresse von www.example.com. Die Anfrage läuft über UDP-Port 53, und die Antwort ist ein A-Record mit der IPv4-Adresse. (In einem Netz mit IPv6 würde er auch nach einem AAAA-Record fragen.)",Resolver:"Resolver","8.8.8.8 (had it cached)":"8.8.8.8 (hatte sie im Cache)","UDP, port 53":"UDP, Port 53",Answer:"Antwort","TCP Connection":"TCP-Verbindung","Establishes a reliable link":"Baut eine zuverlässige Verbindung auf","HTTP runs on top of TCP. Before any page data moves, the laptop and the server open a connection to port 80 with a three-way handshake: SYN, SYN-ACK, ACK.":"HTTP läuft über TCP. Bevor irgendwelche Seitendaten fließen, öffnen Laptop und Server mit einem Drei-Wege-Handshake eine Verbindung zu Port 80: SYN, SYN-ACK, ACK.","Server port":"Server-Port","Client port":"Client-Port",Handshake:"Handshake","HTTP Exchange":"HTTP-Austausch","Request and response messages":"Anfrage- und Antwortnachrichten","The browser sends a GET request with a Host header. The server answers 200 OK with the HTML in the body: 12.2 KB, too big for one packet, so TCP splits it into 9 segments of up to 1460 bytes (drawn here as one).":"Der Browser sendet eine GET-Anfrage mit einem Host-Header. Der Server antwortet mit 200 OK und dem HTML im Body: 12.2 KB, zu groß für ein Paket, also teilt TCP es in 9 Segmente von bis zu 1460 Bytes auf (hier als eines gezeichnet).",Status:"Status",Body:"Body","Sent as":"Gesendet als","12.2 KB in 9 segments":"12.2 KB in 9 Segmenten","Page Rendering":"Seitendarstellung","Browser displays the content":"Der Browser zeigt den Inhalt an","The browser parses the HTML and paints the page. Linked CSS, images and scripts would each start more requests just like this one, reusing the open connection where they can.":"Der Browser parst das HTML und zeichnet die Seite. Verlinktes CSS, Bilder und Skripte würden jeweils weitere Anfragen wie diese starten und dabei, wo möglich, die offene Verbindung wiederverwenden.",Document:"Dokument",Connection:"Verbindung","Kept open for reuse":"Für Wiederverwendung offen gehalten","Seen on the laptop’s home network":"Gesehen im Heimnetz des Laptops",Destination:"Ziel","The router: anything beyond the home network goes to it first.":"Der Router: Alles außerhalb des Heimnetzes geht zuerst an ihn.",Source:"Quelle","The laptop’s network card.":"Die Netzwerkkarte des Laptops.",Type:"Typ","What the frame carries.":"Was der Frame transportiert.","Version, header length":"Version, Headerlänge","IPv4, with no options.":"IPv4, ohne Optionen.","Priority and congestion marks; 0 means ordinary traffic.":"Prioritäts- und Staumarkierungen; 0 heißt normaler Verkehr.","Total length":"Gesamtlänge","This header and everything inside it.":"Dieser Header und alles darin.",Identification:"Identifikation","Lets the receiver reassemble the pieces if the packet gets split.":"Lässt den Empfänger die Teile wieder zusammensetzen, falls das Paket aufgeteilt wird.",Flags:"Flags",none:"keine","Routers may split it if a link is too small.":"Router dürfen es aufteilen, wenn eine Strecke zu klein ist.","Time to live":"Time to Live","Windows starts at 128.":"Windows beginnt bei 128.",Protocol:"Protokoll","Header checksum":"Header-Prüfsumme","Covers this header only; every router recomputes it after lowering the TTL.":"Deckt nur diesen Header ab; jeder Router berechnet sie neu, nachdem er die TTL gesenkt hat.","Source port":"Quellport","Destination port":"Zielport",Length:"Länge","UDP header and data. That is all of UDP: no numbering, no acknowledgements.":"UDP-Header und Daten. Das ist ganz UDP: keine Nummerierung, keine Bestätigungen.",Checksum:"Prüfsumme","Covers the header, the data and the IP addresses.":"Deckt Header, Daten und die IP-Adressen ab.","Transaction ID":"Transaktions-ID","Picked at random; the answer must carry the same one.":"Zufällig gewählt; die Antwort muss dieselbe tragen.","0x0100: query, RD (recursion desired)":"0x0100: Anfrage, RD (Rekursion gewünscht)",Questions:"Fragen",Answers:"Antworten","Authority records":"Autoritätseinträge","Additional records":"Zusätzliche Einträge",Question:"Frage","www.example.com, type A, class IN":"www.example.com, Typ A, Klasse IN","The laptop.":"Der Laptop.","The router’s side facing the home network.":"Die dem Heimnetz zugewandte Seite des Routers.","Started at 128; 10 routers on the way each took 1.":"Begann bei 128; jeder der 10 Router auf dem Weg zog 1 ab.","0x8180: response, RD (recursion desired), RA (recursion available)":"0x8180: Antwort, RD (Rekursion gewünscht), RA (Rekursion verfügbar)","DF (don’t fragment)":"DF (nicht fragmentieren)","Routers must not split it; if it’s too big they report back instead.":"Router dürfen es nicht aufteilen; ist es zu groß, melden sie das zurück.","Picked by the laptop’s system for this connection.":"Vom System des Laptops für diese Verbindung gewählt.","Sequence number":"Sequenznummer","This side’s starting number. Shown as 0; the real one is random.":"Die Startnummer dieser Seite. Als 0 angezeigt; die echte ist zufällig.","Real sequence number":"Echte Sequenznummer",Acknowledgment:"Bestätigung","0 (not used yet)":"0 (noch nicht verwendet)","A first SYN has nothing to acknowledge.":"Ein erstes SYN hat nichts zu bestätigen.","Header length":"Headerlänge","20 bytes, plus 12 of options.":"20 Bytes plus 12 Bytes Optionen.",Window:"Fenster","How much more data this side can take right now.":"Wie viele Daten diese Seite gerade noch aufnehmen kann.","Covers the header, the data and the IP addresses, so damage is caught.":"Deckt Header, Daten und die IP-Adressen ab, damit Schäden auffallen.","Urgent pointer":"Urgent-Zeiger",Options:"Optionen","Maximum segment size":"Maximale Segmentgröße","The most data this side wants in one segment.":"Die meisten Daten, die diese Seite in einem Segment haben will.","Spacing, so the next option lines up.":"Füller, damit die nächste Option ausgerichtet ist.","Window scale":"Fensterskalierung","Window values are multiplied by this, so windows can be larger than 64 KB.":"Fensterwerte werden damit multipliziert, sodass Fenster größer als 64 KB sein können.","SACK permitted":"SACK erlaubt",yes:"ja","This side understands selective acknowledgements.":"Diese Seite versteht selektive Bestätigungen.","Started at 64; 12 routers on the way each took 1.":"Begann bei 64; jeder der 12 Router auf dem Weg zog 1 ab.","The next byte this side expects: everything before it has arrived.":"Das nächste Byte, das diese Seite erwartet: Alles davor ist angekommen.","Position of this segment’s first byte, counted from this side’s SYN.":"Position des ersten Bytes dieses Segments, gezählt ab dem SYN dieser Seite.",Padding:"Auffüllung","Ethernet frames are at least 60 bytes (64 with the checksum the card adds), so short ones are padded.":"Ethernet-Frames sind mindestens 60 Bytes lang (64 mit der Prüfsumme, die die Karte anhängt), daher werden kurze aufgefüllt.",Text:"Text","covers bytes not shown here":"deckt Bytes ab, die hier nicht gezeigt werden","12,500 bytes: the HTML page":"12,500 Bytes: die HTML-Seite","The page itself; its contents are not part of the lesson.":"Die Seite selbst; ihr Inhalt ist nicht Teil der Lektion.","Secure Web":"Sicheres Web","TLS handshake":"TLS-Handshake","HTTP request":"HTTP-Anfrage","HTTP response":"HTTP-Antwort","HTTPS is HTTP sent through an encrypted TLS connection. TLS proves the server is who it claims to be with a certificate, agrees on fresh encryption keys, and then protects every request and response from being read or changed on the way.":"HTTPS ist HTTP, gesendet über eine verschlüsselte TLS-Verbindung. TLS beweist mit einem Zertifikat, dass der Server der ist, für den er sich ausgibt, vereinbart frische Schlüssel und schützt dann jede Anfrage und Antwort davor, unterwegs gelesen oder verändert zu werden.","Application (HTTP over TLS)":"Anwendung (HTTP über TLS)",Security:"Sicherheit","TLS 1.3 (1.2 still common)":"TLS 1.3 (1.2 noch verbreitet)",Proves:"Beweist","Server identity (certificate)":"Serveridentität (Zertifikat)","Secure page delivered":"Sichere Seite ausgeliefert","Encrypted, except the lookup":"Verschlüsselt, bis auf die DNS-Abfrage","The browser looked up the address in plain DNS, opened a TCP connection, checked the server’s certificate and agreed on keys in one round trip. Every HTTP byte after that travelled encrypted. Press REPLAY to watch it again.":"Der Browser hat die Adresse per unverschlüsseltem DNS nachgeschlagen, eine TCP-Verbindung geöffnet, das Zertifikat des Servers geprüft und in einem einzigen Round Trip Schlüssel vereinbart. Jedes HTTP-Byte danach reiste verschlüsselt. Drücke NOCHMAL, um es dir noch einmal anzusehen.",Cipher:"Cipher","Still visible":"Noch sichtbar","IPs, server name, sizes":"IPs, Servername, Größen","Secure Request":"Sichere Anfrage","Browser asks for https://":"Der Browser fragt nach https://","You type https://www.example.com. The “s” tells the browser to protect the connection with TLS, on port 443 by default. Before it can connect at all, it still has to find the server’s IP address.":"Du tippst https://www.example.com. Das „s“ sagt dem Browser, die Verbindung mit TLS zu schützen, standardmäßig auf Port 443. Bevor er sich überhaupt verbinden kann, muss er noch die IP-Adresse des Servers finden.",Port:"Port","DNS Lookup":"DNS-Abfrage","Same lookup as HTTP, not encrypted":"Dieselbe Abfrage wie bei HTTP, unverschlüsselt","The lookup is exactly the same as for plain HTTP: a query to 8.8.8.8 over UDP port 53. It is not encrypted, so anyone on the path can see which name you asked for, unless the browser uses DNS over HTTPS.":"Die Abfrage ist genau dieselbe wie bei einfachem HTTP: eine Anfrage an 8.8.8.8 über UDP-Port 53. Sie ist nicht verschlüsselt, also kann jeder auf dem Weg sehen, nach welchem Namen du gefragt hast, es sei denn, der Browser nutzt DNS over HTTPS.",Encrypted:"Verschlüsselt","No (plain DNS)":"Nein (normales DNS)","TCP Handshake":"TCP-Handshake","Opens a connection to port 443":"Öffnet eine Verbindung zu Port 443","TLS rides on TCP, so the same three-way handshake comes first, this time to port 443. Nothing is encrypted yet.":"TLS läuft auf TCP, also kommt zuerst derselbe Drei-Wege-Handshake, diesmal zu Port 443. Noch ist nichts verschlüsselt.","TLS Handshake":"TLS-Handshake","Agrees on keys, checks the certificate":"Vereinbart Schlüssel, prüft das Zertifikat","The browser offers ciphers and key shares, including a post-quantum hybrid. The server picks it and sends its own share, then its certificate, already encrypted. The browser checks it against authorities it trusts.":"Der Browser bietet Cipher und Key Shares an, darunter einen Post-Quanten-Hybrid. Der Server wählt ihn und schickt seinen eigenen Share, dann sein Zertifikat, bereits verschlüsselt. Der Browser prüft es gegen Zertifizierungsstellen, denen er vertraut.",Version:"Version","Key exchange":"Schlüsselaustausch","X25519MLKEM768 (hybrid)":"X25519MLKEM768 (Hybrid)","Server name":"Servername","Sent in clear (SNI)":"Im Klartext gesendet (SNI)","key shares: hybrid + x25519":"Key Shares: Hybrid + x25519","cipher: AES_128_GCM_SHA256":"Cipher: AES_128_GCM_SHA256","then encrypted: cert, Finished":"dann verschlüsselt: Zert., Finished","handshake complete (encrypted)":"Handshake fertig (verschlüsselt)","Encrypted Exchange":"Verschlüsselter Austausch","HTTP inside TLS records":"HTTP in TLS-Records","The GET and 200 OK are the same HTTP messages as before, sealed in TLS records that look like random “application data” on the wire. The server also hands over two session tickets, so a later visit can skip part of the handshake.":"GET und 200 OK sind dieselben HTTP-Nachrichten wie zuvor, versiegelt in TLS-Records, die auf der Leitung wie zufällige „Anwendungsdaten“ aussehen. Der Server übergibt außerdem zwei Session-Tickets, damit ein späterer Besuch einen Teil des Handshakes überspringen kann.",Inside:"Darin","GET / and 200 OK":"GET / und 200 OK",Tickets:"Tickets","2, for faster reconnects":"2, für schnellere Neuverbindungen","inside: GET / HTTP/1.1":"innen: GET / HTTP/1.1","outside: encrypted bytes":"außen: verschlüsselte Bytes","inside: HTTP/1.1 200 OK":"innen: HTTP/1.1 200 OK","outside: 12.9 KB, 9 segments":"außen: 12.9 KB, 9 Segmente","Browser shows the padlock":"Der Browser zeigt das Schloss","The browser decrypts the response, paints the page and shows a padlock: the connection is private and the server proved its identity. The Strict-Transport-Security header tells it to use HTTPS for this site from now on.":"Der Browser entschlüsselt die Antwort, zeichnet die Seite und zeigt ein Schloss: Die Verbindung ist privat, und der Server hat seine Identität bewiesen. Der Header Strict-Transport-Security sagt ihm, für diese Seite ab jetzt HTTPS zu verwenden.",Remembers:"Merkt sich","HTTPS only (HSTS), 1 year":"Nur HTTPS (HSTS), 1 Jahr","Server Hello + encrypted handshake, 3 segments":"Server Hello + verschlüsselter Handshake, 3 Segmente","Change Cipher Spec, Finished (encrypted)":"Change Cipher Spec, Finished (verschlüsselt)","Application Data (HTTP request)":"Application Data (HTTP-Anfrage)","New Session Ticket ×2 (encrypted)":"New Session Ticket ×2 (verschlüsselt)","Application Data (HTTP response), 9 segments":"Application Data (HTTP-Antwort), 9 Segmente",Record:"Record","Content type":"Inhaltstyp","A Client Hello’s record says TLS 1.0 so old middleboxes let it through; the real versions are offered inside.":"Der Record eines Client Hello gibt TLS 1.0 an, damit alte Middleboxes ihn durchlassen; die echten Versionen werden darin angeboten.","Handshake type":"Handshake-Typ",Contents:"Inhalt","Everything the browser supports. Browsers vary a few details from one connection to the next.":"Alles, was der Browser unterstützt. Browser variieren einige Details von Verbindung zu Verbindung.","Server name (SNI)":"Servername (SNI)","Versions offered":"Angebotene Versionen","Key shares":"Key Shares","App protocols (ALPN)":"Anwendungsprotokolle (ALPN)","TLS 1.3 records say 1.2 on the outside, for compatibility.":"TLS-1.3-Records geben außen 1.2 an, aus Kompatibilitätsgründen.","The server’s choices and its half of the hybrid key exchange.":"Die Auswahl des Servers und seine Hälfte des hybriden Schlüsselaustauschs.","Cipher suite":"Cipher-Suite","Key share":"Key Share","Has no job in TLS 1.3; sent so middleboxes see a familiar handshake.":"Hat in TLS 1.3 keine Aufgabe; wird gesendet, damit Middleboxes einen vertrauten Handshake sehen.","Every encrypted record says Application Data on the outside; the real type is inside.":"Jeder verschlüsselte Record gibt außen Application Data an; der echte Typ steckt darin.","Encrypted data":"Verschlüsselte Daten","Ciphertext, ending in a 16-byte tag that shows any change. Only the two ends can read it.":"Chiffretext, endend mit einem 16-Byte-Tag, das jede Änderung verrät. Nur die beiden Enden können ihn lesen.","Encrypted Extensions (ALPN: http/1.1), Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions (ALPN: http/1.1), Certificate (die Kette), Certificate Verify (die Signatur), Finished","Finished: a check value over the whole handshake":"Finished: ein Prüfwert über den ganzen Handshake","The HTTP request":"Die HTTP-Anfrage","New Session Ticket: lets a later visit resume":"New Session Ticket: lässt einen späteren Besuch die Sitzung fortsetzen","The HTTP response, then the 12,500-byte page":"Die HTTP-Antwort, dann die 12,500 Bytes große Seite","Reliable Delivery":"Zuverlässige Zustellung","Handshake and ACKs":"Handshake und ACKs","Data from laptop":"Daten vom Laptop","Data from server":"Daten vom Server","Closing (FIN)":"Abbau (FIN)","TCP turns the internet’s best-effort packet delivery into a reliable, ordered stream of bytes. It numbers every byte, acknowledges what arrives, resends what goes missing, and paces the sender so neither the other side nor the network is overwhelmed.":"TCP macht aus der Best-Effort-Paketzustellung des Internets einen zuverlässigen, geordneten Bytestrom. Es nummeriert jedes Byte, bestätigt, was ankommt, sendet erneut, was fehlt, und bremst den Sender, damit weder die Gegenseite noch das Netz überlastet wird.","Transport (Layer 4)":"Transport (Schicht 4)","Three-way handshake":"Drei-Wege-Handshake",Reliability:"Zuverlässigkeit","Sequence numbers + ACKs":"Sequenznummern + ACKs",Recovery:"Wiederherstellung",Retransmission:"Neuübertragung",Header:"Header","Connection closed":"Verbindung geschlossen","Every byte accounted for":"Jedes Byte erfasst","TCP opened a connection, numbered and acknowledged every byte, spotted a gap and resent just the missing segment, then closed both directions cleanly. curl received every byte in order and never saw the loss. Press REPLAY to watch it again.":"TCP hat eine Verbindung geöffnet, jedes Byte nummeriert und bestätigt, eine Lücke bemerkt und nur das fehlende Segment erneut gesendet und dann beide Richtungen sauber geschlossen. curl hat jedes Byte in der richtigen Reihenfolge erhalten und den Verlust nie bemerkt. Drücke NOCHMAL, um es dir noch einmal anzusehen.",Segments:"Segmente","14 (1 lost, 1 resent)":"14 (1 verloren, 1 erneut gesendet)","Bytes delivered":"Zugestellte Bytes","78 up, 2,920 down":"78 hoch, 2,920 runter","Loss found by":"Verlust erkannt durch","Duplicate ACK + SACK":"Doppeltes ACK + SACK","Open Connection":"Verbindung öffnen","curl already knows the server’s address. Before any data moves, both sides choose a starting sequence number and confirm it: SYN, SYN-ACK, ACK. The numbers here are relative; real ones start at a random value.":"curl kennt die Adresse des Servers bereits. Bevor Daten fließen, wählen beide Seiten eine Startsequenznummer und bestätigen sie: SYN, SYN-ACK, ACK. Die Nummern hier sind relativ; echte beginnen bei einem Zufallswert.",Server:"Server","203.0.113.10, port 80":"203.0.113.10, Port 80","Send Data":"Daten senden","Every byte is numbered":"Jedes Byte ist nummeriert","curl sends its 78-byte HTTP request: bytes 1 to 78. The server’s ACK number, 79, is the next byte it expects, which means everything before it has arrived.":"curl sendet seine 78 Bytes lange HTTP-Anfrage: Bytes 1 bis 78. Die ACK-Nummer des Servers, 79, ist das nächste Byte, das er erwartet, also ist alles davor angekommen.",Sent:"Gesendet","79 = next byte expected":"79 = nächstes erwartetes Byte","Two Segments Back":"Zwei Segmente zurück","One of them is lost":"Eines davon geht verloren","The server answers with 2,920 bytes: two full segments of 1,460 bytes, the most that fits in one packet here, sent back to back. The first is dropped somewhere on the internet; the second gets through.":"Der Server antwortet mit 2,920 Bytes: zwei volle Segmente zu je 1,460 Bytes, das Maximum, das hier in ein Paket passt, direkt hintereinander gesendet. Das erste geht irgendwo im Internet verloren; das zweite kommt durch.","Segment 1":"Segment 1","bytes 1–1460 (lost)":"Bytes 1–1460 (verloren)","Segment 2":"Segment 2","Segment size":"Segmentgröße","seq=1 and seq=1461":"seq=1 und seq=1461","the first is lost":"das erste geht verloren","A Gap Is Noticed":"Eine Lücke fällt auf","Duplicate ACK with SACK":"Doppeltes ACK mit SACK","Bytes 1461–2920 arrive, but 1–1460 never did. An ACK can only count bytes received in order, so the laptop repeats ACK 1 at once and adds a SACK block saying it already holds 1461–2920.":"Die Bytes 1461–2920 kommen an, 1–1460 aber nie. Ein ACK kann nur in Reihenfolge empfangene Bytes zählen, also wiederholt der Laptop sofort ACK 1 und fügt einen SACK-Block hinzu, der sagt, dass er 1461–2920 schon hat.","1 (still waiting for byte 1)":"1 (wartet noch auf Byte 1)","holds bytes 1461–2920":"hat Bytes 1461–2920","At once, not delayed":"Sofort, nicht verzögert","sack: has 1461–2920":"sack: hat 1461–2920","Resend the Gap":"Die Lücke erneut senden","Only the missing bytes":"Nur die fehlenden Bytes","The SACK tells the server exactly what is missing, so it resends just segment 1, and the laptop acknowledges everything. Had no ACK come back at all, timers would have stepped in: a probe after about two round trips, then a retransmission timeout (at least 200 ms on Linux).":"Der SACK sagt dem Server genau, was fehlt, also sendet er nur Segment 1 erneut, und der Laptop bestätigt alles. Wäre gar kein ACK zurückgekommen, hätten Timer übernommen: zuerst eine Probe nach etwa zwei Umläufen, dann das Neuübertragungs-Timeout (unter Linux mindestens 200 ms).",Resent:"Erneut gesendet","bytes 1–1460 only":"nur Bytes 1–1460","Next ACK":"Nächstes ACK","2921 (everything)":"2921 (alles)","curl saw":"curl sah","Every byte, in order":"Jedes Byte, in Reihenfolge","just the missing segment":"nur das fehlende Segment","Close Connection":"Verbindung schließen","Each side says goodbye":"Jede Seite verabschiedet sich","curl is done, so it closes. Each direction closes on its own: the laptop sends FIN and the server acknowledges it, then the server sends its own FIN and the laptop acknowledges that. The laptop keeps the connection’s details for a while (TIME-WAIT).":"curl ist fertig und schließt deshalb. Jede Richtung schließt für sich: Der Laptop sendet FIN und der Server bestätigt es, dann sendet der Server sein eigenes FIN und der Laptop bestätigt das. Der Laptop behält die Verbindungsdaten noch eine Weile (TIME-WAIT).","Closed by":"Geschlossen durch","A FIN from each side":"Ein FIN von jeder Seite",Order:"Reihenfolge",Then:"Danach","Laptop waits (TIME-WAIT)":"Laptop wartet (TIME-WAIT)",Data:"Daten","1,460 bytes: the HTTP response, bytes 1–1460":"1,460 Bytes: die HTTP-Antwort, Bytes 1–1460","1,460 bytes: the HTTP response, bytes 1461–2920":"1,460 Bytes: die HTTP-Antwort, Bytes 1461–2920","has 1461–2920":"hat 1461–2920","Bytes that arrived after the gap, so only the gap needs resending.":"Bytes, die nach der Lücke ankamen, sodass nur die Lücke erneut gesendet werden muss.","Fast Datagrams":"Schnelle Datagramme","Your voice":"Deine Stimme","Their voice":"Die andere Stimme","Media Server":"Medienserver","UDP sends data in independent packets called datagrams, with no connection, no acknowledgements and no resends. That keeps it fast and light: right for voice, video, games and DNS, where a late answer is worse than a missing one.":"UDP schickt Daten in unabhängigen Paketen, den Datagrammen: ohne Verbindung, ohne Bestätigungen und ohne erneutes Senden. Das hält es schnell und schlank: richtig für Sprache, Video, Spiele und DNS, wo eine verspätete Antwort schlimmer ist als eine fehlende.",None:"Keine","None (no ACKs, no resends)":"Keine (keine ACKs, kein erneutes Senden)",Ordering:"Reihenfolge","Not guaranteed":"Nicht garantiert","Call keeps flowing":"Das Gespräch läuft weiter","Fast, simple, no guarantees":"Schnell, einfach, ohne Garantien","Audio started with the very first packet, every datagram travelled on its own, and the one that was lost was simply gone: UDP never noticed. The app covered the gap and the call carried on. Press REPLAY to watch it again.":"Der Ton begann schon mit dem allerersten Paket, jedes Datagramm reiste für sich, und das verlorene war einfach weg: UDP hat es nie bemerkt. Die App hat die Lücke überbrückt, und das Gespräch lief weiter. Drücke NOCHMAL, um es dir noch einmal anzusehen.",Datagrams:"Datagramme","11 (1 lost, never resent)":"11 (1 verloren, nie erneut gesendet)","Setup time":"Aufbauzeit","0 ms (no handshake)":"0 ms (kein Handshake)",Shown:"Gezeigt","The first 0.2 s of a call":"Die ersten 0.2 s eines Anrufs","Send Right Away":"Sofort senden","No handshake, data goes first":"Kein Handshake, die Daten gehen zuerst","A call app already knows the media server’s address and port from signing in. It doesn’t open a connection: the very first datagram already carries 20 ms of your voice, behind an 8-byte UDP header.":"Eine Anruf-App kennt Adresse und Port des Medienservers schon von der Anmeldung. Sie baut keine Verbindung auf: Schon das allererste Datagramm trägt 20 ms deiner Stimme, hinter einem 8 Byte langen UDP-Header.",Setup:"Aufbau",Ports:"Ports","92 B of audio, no setup":"92 B Ton, kein Aufbau","A Stream of Datagrams":"Ein Strom von Datagrammen","One every 20 ms, each on its own":"Eins alle 20 ms, jedes für sich","The app keeps sending a datagram every 20 ms. Each one stands alone, with its own header and no link to the others. UDP doesn’t number them, and nothing comes back to confirm they arrived.":"Die App schickt weiter alle 20 ms ein Datagramm. Jedes steht für sich, mit eigenem Header und ohne Bezug zu den anderen. UDP nummeriert sie nicht, und nichts kommt zurück, um ihre Ankunft zu bestätigen.",Rate:"Takt","1 datagram / 20 ms":"1 Datagramm / 20 ms",Numbering:"Nummerierung","None in UDP itself":"Keine in UDP selbst",Confirmation:"Bestätigung","None (no ACKs)":"Keine (keine ACKs)","voice frames 2–5":"Sprachrahmen 2–5","each with its own 8-byte header":"jeder mit eigenem 8-Byte-Header","Lost on the Way":"Unterwegs verloren","Nobody resends it":"Niemand sendet ihn erneut","Frame 7 is dropped somewhere on the internet. The media server never asks for it, and UDP never tells the laptop: there are no acknowledgements to miss. The datagrams after it arrive as normal.":"Rahmen 7 geht irgendwo im Internet verloren. Der Medienserver fordert ihn nie an, und UDP sagt dem Laptop nie Bescheid: Es gibt keine Bestätigungen, deren Fehlen auffallen könnte. Die Datagramme danach kommen ganz normal an.",Lost:"Verloren","Voice frame 7":"Sprachrahmen 7","Never (no ACKs)":"Nie (keine ACKs)",Missing:"Fehlt","20 ms of audio":"20 ms Ton","voice frames 6–8":"Sprachrahmen 6–8","frame 7 is lost":"Rahmen 7 geht verloren","Replies Come Back":"Antworten kommen zurück","The other voice comes back":"Die andere Stimme kommt zurück","The other person’s voice arrives the same way, as separate datagrams sent to port 50000. They get back in because your router remembered the outgoing port when it translated your address (NAT).":"Die Stimme der anderen Person kommt genauso an, als einzelne Datagramme an Port 50000. Sie kommen herein, weil sich dein Router den ausgehenden Port gemerkt hat, als er deine Adresse übersetzt hat (NAT).",Direction:"Richtung","Independent of ours":"Unabhängig von unserer","Through NAT":"Durch NAT","Router remembers the port":"Der Router merkt sich den Port","the other person’s voice":"die Stimme der anderen Person","sent to port 50000":"an Port 50000 gesendet","The App Decides":"Die App entscheidet","Reliability is up to the app":"Zuverlässigkeit ist Sache der App","The call app numbers its own frames (RTP does this), so it sees that frame 7 is missing and smooths over the 20 ms gap instead of waiting. Waiting for a resend would make the whole call lag.":"Die Anruf-App nummeriert ihre Rahmen selbst (das macht RTP), sieht also, dass Rahmen 7 fehlt, und glättet die 20-ms-Lücke, statt zu warten. Auf ein erneutes Senden zu warten, würde das ganze Gespräch verzögern.","App’s job (e.g. RTP)":"Aufgabe der App (z. B. RTP)",Loss:"Verlust","Hidden by the app":"Von der App verdeckt","Also on UDP":"Ebenfalls über UDP","DNS, games, QUIC":"DNS, Spiele, QUIC","Version etc.":"Version usw.","2, no padding, no extension, no CSRCs":"2, kein Padding, keine Erweiterung, keine CSRCs","Marker, payload type":"Marker, Nutzdatentyp","1, 111 (Opus, agreed when the call was set up)":"1, 111 (Opus, beim Aufbau des Anrufs vereinbart)","Counts up by one per packet, so the app can spot a missing or late one.":"Zählt pro Paket um eins hoch, damit die App ein fehlendes oder verspätetes erkennt.",Timestamp:"Zeitstempel","Audio clock at 48,000 per second: +960 per 20 ms frame.":"Audiotakt mit 48,000 pro Sekunde: +960 pro 20-ms-Rahmen.","Identifies this audio stream.":"Kennzeichnet diesen Audiostrom.",Audio:"Audio","80 bytes of Opus audio (20 ms)":"80 Byte Opus-Audio (20 ms)","0, 111 (Opus, agreed when the call was set up)":"0, 111 (Opus, beim Aufbau des Anrufs vereinbart)","Addressing & Routing":"Adressierung und Routing","Outgoing packet":"Ausgehendes Paket",Reply:"Antwort","IP gives every device an address and moves packets from network to network. Each router looks only at the destination address to choose the next hop. IP is best effort: it doesn’t promise delivery or order. TCP adds those on top.":"IP gibt jedem Gerät eine Adresse und bringt Pakete von Netz zu Netz. Jeder Router schaut nur auf die Zieladresse, um den nächsten Hop zu wählen. IP arbeitet nach dem Best-Effort-Prinzip: Es verspricht weder Zustellung noch Reihenfolge. Das fügt TCP obendrauf hinzu.","Network (Layer 3)":"Vermittlung (Schicht 3)",Address:"Adresse","Lowered by 1 at each router":"An jedem Router um 1 gesenkt",Delivery:"Zustellung","Best effort":"Best Effort","There and back":"Hin und zurück","Twelve routers each way":"Zwölf Router in jede Richtung","The laptop sent the packet to its router, which swapped in its public address. Twelve routers in all passed it along by destination address alone, and the reply found its way back the same way. Press REPLAY to watch it again.":"Der Laptop schickte das Paket an seinen Router, der seine öffentliche Adresse einsetzte. Insgesamt zwölf Router reichten es allein anhand der Zieladresse weiter, und die Antwort fand auf dieselbe Weise zurück. Drücke NOCHMAL, um es dir noch einmal anzusehen.",Routers:"Router","12 each way (1 home + 11)":"12 pro Richtung (1 daheim + 11)","TTL at server":"TTL am Server","116 (sent with 128)":"116 (mit 128 gesendet)","Rewritten by NAT":"Von NAT umgeschrieben","Source out, destination back":"Quelle hin, Ziel zurück","IPv4 (IPv6 works alike)":"IPv4 (IPv6 funktioniert genauso)","Local or Not?":"Lokal oder nicht?","Compare the address with the subnet":"Adresse mit dem Subnetz vergleichen","The laptop is 192.168.1.10 with a /24 mask, so its own network is 192.168.1.0 to 192.168.1.255. The server, 203.0.113.10, is outside that range, so the packet has to go to the default gateway: the home router.":"Der Laptop hat 192.168.1.10 mit einer /24-Maske, sein eigenes Netz reicht also von 192.168.1.0 bis 192.168.1.255. Der Server, 203.0.113.10, liegt außerhalb dieses Bereichs, also muss das Paket zum Standardgateway: dem Router zu Hause.",Laptop:"Laptop","Local range":"Lokaler Bereich",Gateway:"Gateway","Find the Router":"Den Router finden","ARP turns an IP into a MAC":"ARP macht aus einer IP eine MAC","On the local network, frames are delivered by MAC address. If the router’s MAC isn’t in the laptop’s ARP cache, it broadcasts “who has 192.168.1.1?” and the router answers with its MAC address.":"Im lokalen Netz werden Frames per MAC-Adresse zugestellt. Steht die MAC des Routers nicht im ARP-Cache des Laptops, fragt er per Broadcast „Wer hat 192.168.1.1?“, und der Router antwortet mit seiner MAC-Adresse.",Asks:"Fragt","Who has 192.168.1.1?":"Wer hat 192.168.1.1?","Sent to":"Gesendet an","Everyone (broadcast)":"Alle (Broadcast)",Learns:"Erfährt","Router’s MAC address":"MAC-Adresse des Routers","who has 192.168.1.1?":"wer hat 192.168.1.1?","tell 192.168.1.10":"an 192.168.1.10 melden","Send the Packet":"Das Paket senden","Addresses, TTL and protocol":"Adressen, TTL und Protokoll","The IP header carries the source and destination addresses, a TTL and the protocol inside. Here it holds a TCP SYN to port 443. Windows starts the TTL at 128 (Linux and macOS use 64).":"Der IP-Header enthält Quell- und Zieladresse, eine TTL und das enthaltene Protokoll. Hier steckt ein TCP-SYN an Port 443 darin. Windows beginnt die TTL bei 128 (Linux und macOS nehmen 64).","From → to":"Von → an","TTL 128 · protocol TCP":"TTL 128 · Protokoll TCP","NAT, Then Hop by Hop":"NAT, dann Hop für Hop","The router rewrites and forwards":"Der Router schreibt um und leitet weiter","The router swaps the private source for its public address 198.51.100.7 (and here port 52344 for 40112), notes the mapping, and lowers the TTL to 127. Then 11 routers on the internet each choose the next hop by destination and lower the TTL again.":"Der Router ersetzt die private Quelle durch seine öffentliche Adresse 198.51.100.7 (und hier Port 52344 durch 40112), notiert die Zuordnung und senkt die TTL auf 127. Dann wählen 11 Router im Internet jeweils anhand des Ziels den nächsten Hop und senken die TTL weiter.","New source":"Neue Quelle","Leaves home":"Verlässt das Zuhause","At the server":"Am Server","TTL 116 (11 more hops)":"TTL 116 (11 Hops mehr)","TTL 127 · after NAT":"TTL 127 · nach NAT","The Reply Comes Back":"Die Antwort kommt zurück","NAT translates it for the laptop":"NAT übersetzt sie für den Laptop","The server answers the address it saw, 198.51.100.7:40112. The router looks that up in its NAT table, rewrites the destination back to 192.168.1.10:52344 and passes it on. The reply started at TTL 64 and arrives with 52.":"Der Server antwortet an die Adresse, die er gesehen hat, 198.51.100.7:40112. Der Router schlägt sie in seiner NAT-Tabelle nach, schreibt das Ziel zurück auf 192.168.1.10:52344 und gibt sie weiter. Die Antwort startete mit TTL 64 und kommt mit 52 an.","Delivered to":"Zugestellt an","TTL 52 · after NAT":"TTL 52 · nach NAT","TTL 127 · 40112 → 443 [SYN] (after NAT)":"TTL 127 · 40112 → 443 [SYN] (nach NAT)","TTL 52 · 443 → 52344 [SYN, ACK] (after NAT)":"TTL 52 · 443 → 52344 [SYN, ACK] (nach NAT)","ARP request · 28 bytes":"ARP-Anfrage · 28 Byte","Broadcast: every device on the network receives it.":"Broadcast: Jedes Gerät im Netz empfängt sie.","The sender’s network card.":"Die Netzwerkkarte des Absenders.","Hardware type":"Hardwaretyp","Protocol type":"Protokolltyp","Address sizes":"Adresslängen",Operation:"Operation","1 (request: who has …?)":"1 (Anfrage: Wer hat …?)","Sender MAC":"Absender-MAC","Sender IP":"Absender-IP","Target MAC":"Ziel-MAC","All zeros: this is what the request wants to find out.":"Nur Nullen: Genau das will die Anfrage herausfinden.","Target IP":"Ziel-IP","ARP reply · 28 bytes":"ARP-Antwort · 28 Byte","Straight back to the device that asked.":"Direkt zurück an das Gerät, das gefragt hat.","2 (reply: … is at …)":"2 (Antwort: … ist bei …)","Seen as it leaves the router’s internet side":"Gesehen beim Verlassen der Internetseite des Routers","The internet provider’s router, the next hop.":"Der Router des Internetanbieters, der nächste Hop.","The router’s internet-facing port.":"Der zum Internet zeigende Anschluss des Routers.","As sent: this system starts at 64.":"Wie gesendet: Dieses System beginnt bei 64.","The router’s NAT swapped in its own port for the laptop’s.":"Das NAT des Routers hat den Port des Laptops durch seinen eigenen ersetzt.","The sender’s next router; each hop puts the packet in a new frame.":"Der nächste Router des Absenders; bei jedem Hop kommt das Paket in einen neuen Frame.","Name Resolution":"Namensauflösung",Query:"Anfrage",Referral:"Verweis","DNSSEC not requested here":"DNSSEC hier nicht angefordert","DNS turns names like www.example.com into the IP addresses computers use to reach each other. No single server knows every name: the system is a hierarchy of servers, and answers are cached along the way so most lookups never have to go far.":"DNS macht aus Namen wie www.example.com die IP-Adressen, über die sich Computer erreichen. Kein einzelner Server kennt alle Namen: Das System ist eine Hierarchie von Servern, und Antworten werden unterwegs zwischengespeichert, sodass die meisten Abfragen nie weit gehen müssen.","53, UDP (TCP if large)":"53, UDP (TCP, wenn groß)",Turns:"Macht aus","Names into IP addresses":"Namen IP-Adressen",Hierarchy:"Hierarchie","Root → TLD → authoritative":"Root → TLD → autoritativ",Caching:"Caching","For each record’s TTL":"Für die TTL jedes Eintrags","Name resolved":"Name aufgelöst","And remembered for an hour":"Und eine Stunde lang gemerkt","Starting from an empty cache, the resolver walked from the root to .com to example.com’s own server, then answered the laptop. Until the TTL runs out, the next lookup for this name is answered straight from a cache. Press REPLAY to watch it again.":"Mit leerem Cache ging der Resolver von der Root über .com zum eigenen Server von example.com und antwortete dann dem Laptop. Bis die TTL abläuft, wird die nächste Abfrage dieses Namens direkt aus einem Cache beantwortet. Drücke NOCHMAL, um es dir noch einmal anzusehen.",Queries:"Anfragen","4 (laptop 1, resolver 3)":"4 (Laptop 1, Resolver 3)","Cached for":"Zwischengespeichert für","Ask the Resolver":"Den Resolver fragen","The laptop hands the question off":"Der Laptop gibt die Frage ab","The browser needs the IP address of www.example.com and neither it nor Windows has one cached. The laptop sends one question to the recursive resolver it was given, 8.8.8.8, and asks it to do the whole lookup (recursion desired).":"Der Browser braucht die IP-Adresse von www.example.com, und weder er noch Windows hat sie im Cache. Der Laptop schickt eine einzige Frage an den ihm zugewiesenen rekursiven Resolver, 8.8.8.8, und bittet ihn, die ganze Abfrage zu erledigen (Rekursion gewünscht).","www.example.com, type A":"www.example.com, Typ A",Asked:"Gefragt","8.8.8.8 (recursive)":"8.8.8.8 (rekursiv)","RD (recursion desired)":"RD (Rekursion gewünscht)","flags: RD":"Flags: RD","Points the way to .com":"Weist den Weg zu .com","The resolver’s cache is empty (it has just started), so it begins at the top. A root server doesn’t know the address, but it knows which servers handle .com and replies with a referral. Many resolvers send it only “com”, not the full name.":"Der Cache des Resolvers ist leer (er ist gerade gestartet), also fängt er ganz oben an. Ein Root-Server kennt die Adresse nicht, weiß aber, welche Server für .com zuständig sind, und antwortet mit einem Verweis. Viele Resolver schicken ihm nur „com“, nicht den ganzen Namen.","Root servers":"Root-Server","13 names, 1,000+ anycast sites":"13 Namen, über 1,000 Anycast-Standorte","Referral (13 .com servers)":"Verweis (13 .com-Server)","no answer: ask .com":"keine Antwort: frag .com","Points the way to example.com":"Weist den Weg zu example.com","The resolver asks one of the .com servers. They don’t store addresses for every site either, but they know which name servers each .com domain uses, so this reply is another referral, with those servers’ addresses (glue) attached.":"Der Resolver fragt einen der .com-Server. Auch sie speichern nicht die Adressen aller Websites, wissen aber, welche Nameserver jede .com-Domain nutzt. Diese Antwort ist also ein weiterer Verweis, mit den Adressen dieser Server (Glue) dabei.",Knows:"Kennt","Name servers of .com domains":"Nameserver der .com-Domains","Referral + glue addresses":"Verweis + Glue-Adressen","no answer: ask example.com":"keine Antwort: frag example.com","Gives the actual answer":"Gibt die eigentliche Antwort","Finally the resolver asks example.com’s own name server, which holds the domain’s records. It answers with the A record and marks the reply authoritative. The domain owner sets how long it may be cached: here, 3600 seconds.":"Schließlich fragt der Resolver den eigenen Nameserver von example.com, der die Einträge der Domain hat. Er antwortet mit dem A-Eintrag und kennzeichnet die Antwort als autoritativ. Wie lange sie zwischengespeichert werden darf, legt der Domaininhaber fest: hier 3600 Sekunden.","AA (authoritative), TTL 3600":"AA (autoritativ), TTL 3600","TTL 3600 · flag AA":"TTL 3600 · Flag AA","Answer & Cache":"Antwort und Cache","The laptop gets its address":"Der Laptop bekommt seine Adresse","The resolver sends the answer back to the laptop and keeps a copy. For the next hour it can answer this name straight away, which is why the lookup in the HTTP lesson took only 24 ms. The laptop caches it too.":"Der Resolver schickt die Antwort an den Laptop zurück und behält eine Kopie. In der nächsten Stunde kann er diesen Namen sofort beantworten, deshalb dauerte die Abfrage in der HTTP-Lektion nur 24 ms. Auch der Laptop speichert sie zwischen.","RD, RA (recursion available)":"RD, RA (Rekursion verfügbar)","Cached by":"Zwischengespeichert von","Resolver and laptop":"Resolver und Laptop","flags: RD RA":"Flags: RD RA","Referral: com. NS ×13 (with glue)":"Verweis: com. NS ×13 (mit Glue)","Referral: example.com. NS ×2 (with glue)":"Verweis: example.com. NS ×2 (mit Glue)","Response A 203.0.113.10 (authoritative)":"Antwort A 203.0.113.10 (autoritativ)","As sent: this system starts at 128.":"Wie gesendet: Dieses System beginnt bei 128.","0x0000: query":"0x0000: Anfrage","UDP size 1232, DNSSEC OK = 0":"UDP-Größe 1232, DNSSEC OK = 0","Says how big a UDP answer can be. DNSSEC signatures are not asked for here, to keep the lesson short; a validating resolver like 8.8.8.8 does ask for them.":"Gibt an, wie groß eine UDP-Antwort sein darf. DNSSEC-Signaturen werden hier nicht angefordert, damit die Lektion kurz bleibt; ein validierender Resolver wie 8.8.8.8 fordert sie an.","0x8000: response":"0x8000: Antwort",Authority:"Autorität",Additional:"Zusätzlich","0x8400: response, AA (authoritative)":"0x8400: Antwort, AA (autoritativ)","Getting an Address":"Eine Adresse bekommen","From the laptop":"Vom Laptop","From the DHCP server":"Vom DHCP-Server","Dynamic Host Configuration Protocol":"Protokoll zur dynamischen Host-Konfiguration","DHCP hands a device everything it needs to use a network: an IP address, the subnet mask, the router to send traffic through and the DNS servers to ask. Addresses are leased for a set time and renewed while the device stays on the network.":"DHCP gibt einem Gerät alles, was es braucht, um ein Netz zu nutzen: eine IP-Adresse, die Subnetzmaske, den Router, über den der Verkehr läuft, und die DNS-Server, die es fragen soll. Adressen werden für eine feste Zeit verliehen (Lease) und verlängert, solange das Gerät im Netz bleibt.","UDP 67 (server), 68 (client)":"UDP 67 (Server), 68 (Client)","Hands out":"Vergibt","IP, mask, gateway, DNS":"IP, Maske, Gateway, DNS",Exchange:"Austausch",Lease:"Lease","Renewed at half its time":"Zur Hälfte der Zeit verlängert","On the network":"Im Netz","Leased, and kept up to date":"Geleast und aktuell gehalten","Four messages took the laptop from no address to a working configuration, and halfway through the 24-hour lease it renewed it with a direct request to the router. Press REPLAY to watch it again.":"Vier Nachrichten brachten den Laptop von keiner Adresse zu einer funktionierenden Konfiguration, und nach der Hälfte der 24-Stunden-Lease verlängerte er sie mit einer direkten Anfrage an den Router. Drücke NOCHMAL, um es dir noch einmal anzusehen.",Messages:"Nachrichten","4 to join, 2 per renewal":"4 zum Beitreten, 2 pro Verlängerung","24 h, renewed at 12 h":"24 h, verlängert nach 12 h","No Address Yet":"Noch keine Adresse","The laptop joins the network":"Der Laptop tritt dem Netz bei","The laptop has just connected. It has a MAC address built in, but no IP address, no gateway and no DNS server, so it can’t talk to anything beyond its own network yet. It asks for them with DHCP.":"Der Laptop hat sich gerade verbunden. Er hat eine fest eingebaute MAC-Adresse, aber keine IP-Adresse, kein Gateway und keinen DNS-Server, kann also noch mit nichts außerhalb seines eigenen Netzes reden. Das alles fragt er per DHCP an.","IP address":"IP-Adresse","None (uses 0.0.0.0)":"Keine (nutzt 0.0.0.0)","MAC address":"MAC-Adresse",Needs:"Braucht",Discover:"Suche","Shout to the whole network":"Ruf ins ganze Netz","Without an address of its own, the laptop sends from 0.0.0.0 to the broadcast address 255.255.255.255, so every device on the local network receives it. Only DHCP servers answer.":"Ohne eigene Adresse sendet der Laptop von 0.0.0.0 an die Broadcast-Adresse 255.255.255.255, sodass jedes Gerät im lokalen Netz die Nachricht empfängt. Nur DHCP-Server antworten.",From:"Von","0.0.0.0, UDP port 68":"0.0.0.0, UDP-Port 68","255.255.255.255, port 67":"255.255.255.255, Port 67",Carries:"Enthält","MAC, transaction ID":"MAC, Transaktions-ID","any DHCP server out there?":"ist da draußen ein DHCP-Server?",Offer:"Angebot","The router proposes an address":"Der Router schlägt eine Adresse vor","The router’s DHCP server picks a free address and offers it with the rest of the settings. The laptop can’t use an IP address yet, so the offer goes straight to its MAC address (some clients ask for a broadcast instead).":"Der DHCP-Server des Routers wählt eine freie Adresse und bietet sie mit den übrigen Einstellungen an. Der Laptop kann noch keine IP-Adresse nutzen, also geht das Angebot direkt an seine MAC-Adresse (manche Clients bitten stattdessen um einen Broadcast).",Offered:"Angeboten","Gateway, DNS":"Gateway, DNS","offer: 192.168.1.10/24":"Angebot: 192.168.1.10/24","gateway, DNS, lease 24 h":"Gateway, DNS, Lease 24 h","Accept, out loud":"Annehmen, laut","The laptop asks for the offered address, naming the server it chose. It still broadcasts, so any other DHCP server that made an offer learns it wasn’t picked and can release its address.":"Der Laptop fordert die angebotene Adresse an und nennt dabei den Server, den er gewählt hat. Er sendet weiter per Broadcast, damit jeder andere DHCP-Server, der ein Angebot gemacht hat, erfährt, dass er nicht gewählt wurde, und seine Adresse freigeben kann.",Requests:"Fordert an","Chosen server":"Gewählter Server","I’ll take 192.168.1.10":"Ich nehme 192.168.1.10","from server 192.168.1.1":"von Server 192.168.1.1",Acknowledge:"Bestätigung","The address is the laptop’s":"Die Adresse gehört dem Laptop","The server confirms, and the laptop configures its address, mask, gateway and DNS server. Many systems first check with ARP that no other device is already using the address.":"Der Server bestätigt, und der Laptop richtet Adresse, Maske, Gateway und DNS-Server ein. Viele Systeme prüfen vorher per ARP, ob nicht schon ein anderes Gerät die Adresse nutzt.","DNS server":"DNS-Server","192.168.1.10 is yours":"192.168.1.10 gehört dir","for 24 hours":"für 24 Stunden",Renew:"Verlängern","Halfway through the lease":"Zur Hälfte der Lease","Twelve hours later, half the lease has passed. The laptop now has an address, so it asks the router directly to extend the lease, and the router resets it to 24 hours. If the router didn’t answer, it would broadcast at 87.5%.":"Zwölf Stunden später ist die Hälfte der Lease vorbei. Der Laptop hat jetzt eine Adresse, also bittet er den Router direkt, die Lease zu verlängern, und der Router setzt sie wieder auf 24 Stunden. Würde der Router nicht antworten, würde er bei 87.5 % einen Broadcast senden.",When:"Wann","50% of lease (T1 = 12 h)":"50 % der Lease (T1 = 12 h)","The router (unicast)":"Der Router (Unicast)","If unanswered":"Ohne Antwort","Broadcast at 87.5% (T2)":"Broadcast bei 87.5 % (T2)","renew 192.168.1.10":"192.168.1.10 verlängern","sent straight to 192.168.1.1":"direkt an 192.168.1.1 gesendet","lease renewed":"Lease verlängert","another 24 hours":"weitere 24 Stunden",Message:"Nachricht","1 (request, from a client)":"1 (Anfrage, von einem Client)",Hardware:"Hardware","Ethernet, 6-byte addresses":"Ethernet, 6-Byte-Adressen",Hops:"Hops","Chosen by the client; every reply repeats it.":"Vom Client gewählt; jede Antwort wiederholt sie.",Seconds:"Sekunden","0x0000 (unicast replies are fine)":"0x0000 (Unicast-Antworten sind in Ordnung)","Broadcast flag off: the server may send straight to the client’s MAC address.":"Broadcast-Flag aus: Der Server darf direkt an die MAC-Adresse des Clients senden.","Client address":"Client-Adresse","Filled in only when the client already has an address (renewing).":"Nur ausgefüllt, wenn der Client schon eine Adresse hat (Verlängerung).","Your address":"Deine Adresse","The address the server is giving out.":"Die Adresse, die der Server vergibt.","Next server":"Nächster Server","Relay agent":"Relay-Agent","Client MAC":"Client-MAC","Server name, boot file":"Servername, Bootdatei",empty:"leer","Magic cookie":"Magic Cookie","Marks the options that follow as DHCP.":"Kennzeichnet die folgenden Optionen als DHCP.","Message type: 1 (Discover)":"Nachrichtentyp: 1 (Discover)","Client identifier: 01 00:00:5e:00:53:10":"Client-Kennung: 01 00:00:5e:00:53:10","Host name: alice-laptop":"Hostname: alice-laptop","Vendor class: MSFT 5.0":"Herstellerklasse: MSFT 5.0","Parameters wanted: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252":"Gewünschte Parameter: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252","2 (reply, from a server)":"2 (Antwort, von einem Server)","Message type: 2 (Offer)":"Nachrichtentyp: 2 (Offer)","Server identifier: 192.168.1.1":"Server-Kennung: 192.168.1.1","Lease time: 86,400 s (24 h)":"Lease-Dauer: 86,400 s (24 h)","Renewal time (T1): 43,200 s (12 h)":"Verlängerungszeit (T1): 43,200 s (12 h)","Rebinding time (T2): 75,600 s (21 h)":"Neubindungszeit (T2): 75,600 s (21 h)","Subnet mask: 255.255.255.0":"Subnetzmaske: 255.255.255.0","Broadcast address: 192.168.1.255":"Broadcast-Adresse: 192.168.1.255","DNS server: 8.8.8.8":"DNS-Server: 8.8.8.8","Message type: 3 (Request)":"Nachrichtentyp: 3 (Request)","Requested address: 192.168.1.10":"Angeforderte Adresse: 192.168.1.10","Client FQDN: alice-laptop":"Client-FQDN: alice-laptop","Message type: 5 (ACK)":"Nachrichtentyp: 5 (ACK)","Network Diagnostics":"Netzwerkdiagnose","Ping / probe":"Ping / Test","Echo reply":"Echo-Antwort","Error report":"Fehlermeldung","Internet Control Message Protocol":"Internet-Steuernachrichtenprotokoll","ICMP is how the network reports back: a router says a packet’s time ran out, a server says nothing is listening on a port. Tools like ping and traceroute are built from these messages. It travels inside IP but carries no application data.":"Über ICMP meldet sich das Netz zurück: Ein Router meldet, dass die Zeit eines Pakets abgelaufen ist, ein Server meldet, dass an einem Port nichts lauscht. Werkzeuge wie ping und traceroute bestehen aus diesen Nachrichten. ICMP reist in IP, trägt aber keine Anwendungsdaten.","Carried in":"Steckt in","IP (protocol 1)":"IP (Protokoll 1)","A type and a code":"Ein Typ und ein Code",Tools:"Werkzeuge",Often:"Oft","Filtered by firewalls":"Von Firewalls gefiltert","The network answered":"Das Netz hat geantwortet","Replies, expiries and errors":"Antworten, Abläufe und Fehler","An echo request measured the round trip, packets with a small TTL made each router on the path identify itself, and a closed port was reported straight back. Press REPLAY to watch it again.":"Eine Echo-Anfrage hat die Umlaufzeit gemessen, Pakete mit kleiner TTL brachten jeden Router auf dem Weg dazu, sich zu melden, und ein geschlossener Port wurde sofort zurückgemeldet. Drücke NOCHMAL, um es dir noch einmal anzusehen.","Round trip":"Umlaufzeit",Path:"Weg","12 routers, server at hop 13":"12 Router, Server bei Hop 13","Types used":"Genutzte Typen","8, 0, 11 and 3":"8, 0, 11 und 3","Reply TTL":"TTL der Antwort",Ping:"Ping","Echo request":"Echo-Anfrage","“ping -n 1 203.0.113.10” sends one ICMP echo request (plain ping sends four, a second apart): type 8, code 0, with an identifier, a sequence number and 32 bytes of filler. The server’s system answers by itself, no application needed.":"„ping -n 1 203.0.113.10“ sendet eine ICMP-Echo-Anfrage (einfaches ping sendet vier, im Abstand von einer Sekunde): Typ 8, Code 0, mit einer Kennung, einer Sequenznummer und 32 Byte Füllung. Das System des Servers antwortet von selbst, ganz ohne Anwendung.","Type, code":"Typ, Code","8, 0 (echo request)":"8, 0 (Echo-Anfrage)","type 8 · seq 1":"Typ 8 · Seq 1","32 bytes of data":"32 Byte Daten","Echo Reply":"Echo-Antwort","Round-trip time":"Umlaufzeit","The server sends back an echo reply, type 0, with the same identifier, sequence number and data. Ping prints the time it took and the TTL the reply arrived with: “bytes=32 time=34ms TTL=52”.":"Der Server schickt eine Echo-Antwort zurück, Typ 0, mit derselben Kennung, Sequenznummer und denselben Daten. Ping zeigt die Dauer an und die TTL, mit der die Antwort ankam: „Bytes=32 Zeit=34ms TTL=52“.","0, 0 (echo reply)":"0, 0 (Echo-Antwort)","TTL on arrival":"TTL bei Ankunft","type 0 · seq 1":"Typ 0 · Seq 1","same 32 bytes back":"dieselben 32 Byte zurück","The first router answers":"Der erste Router antwortet","“ping -n 1 -i 1” sends the same request with a TTL of 1. The home router lowers it to 0, so it must drop the packet, and it sends back a Time Exceeded message from its own address: “Reply from 192.168.1.1: TTL expired in transit.”":"„ping -n 1 -i 1“ sendet dieselbe Anfrage mit einer TTL von 1. Der Router zu Hause senkt sie auf 0, muss das Paket also verwerfen, und schickt von seiner eigenen Adresse eine Time-Exceeded-Nachricht (Zeit überschritten) zurück: „Antwort von 192.168.1.1: TTL beim Transport abgelaufen.“","Sent with":"Gesendet mit","Dropped by":"Verworfen von","11, 0 (time exceeded)":"11, 0 (Zeit überschritten)","echo request":"Echo-Anfrage","expires at the first router":"läuft am ersten Router ab","type 11 · from 192.168.1.1":"Typ 11 · von 192.168.1.1","quotes the dropped header":"zitiert den verworfenen Header","The next router answers":"Der nächste Router antwortet","With “-i 2”, the home router lowers the TTL to 1 and forwards it. The first router at the internet provider lowers it to 0 and reports back from 198.51.100.1. The home router translates the report back to the laptop like any reply.":"Mit „-i 2“ senkt der Router zu Hause die TTL auf 1 und leitet weiter. Der erste Router beim Internetanbieter senkt sie auf 0 und meldet sich von 198.51.100.1 zurück. Der Router zu Hause übersetzt die Meldung wie jede Antwort zurück an den Laptop.","ISP router 198.51.100.1":"Provider-Router 198.51.100.1","expires at the second router":"läuft am zweiten Router ab","type 11 · from 198.51.100.1":"Typ 11 · von 198.51.100.1","That’s Traceroute":"Das ist Traceroute","TTL 1, 2, 3 … until it arrives":"TTL 1, 2, 3 … bis zur Ankunft","tracert automates this: it raises the TTL by one each time, sends three probes per hop and lists who reports back. Hops 3 to 12 work the same way, and with TTL 13 the request finally reaches the server, which replies normally.":"tracert automatisiert das: Es erhöht die TTL jedes Mal um eins, sendet drei Tests pro Hop und listet auf, wer sich meldet. Die Hops 3 bis 12 funktionieren genauso, und mit TTL 13 erreicht die Anfrage endlich den Server, der normal antwortet.","12 routers, then the server":"12 Router, dann der Server","Per hop":"Pro Hop","3 probes":"3 Tests","On Linux":"Unter Linux","traceroute sends UDP":"traceroute sendet UDP","enough hops to arrive":"genug Hops zum Ankommen","the server itself answers":"der Server selbst antwortet","end of the route":"Ende der Route",Unreachable:"Unerreichbar","Nothing listening on that port":"An diesem Port lauscht nichts","An app sends a UDP datagram to port 9999, where nothing is listening. The server can’t deliver it, so it replies with Destination Unreachable, code 3 (port unreachable), quoting the start of the datagram. Many firewalls drop such packets silently instead.":"Eine App schickt ein UDP-Datagramm an Port 9999, an dem nichts lauscht. Der Server kann es nicht zustellen, also antwortet er mit „Ziel unerreichbar“, Code 3 (Port unerreichbar), und zitiert den Anfang des Datagramms. Viele Firewalls verwerfen solche Pakete stattdessen stillschweigend.","3, 3 (port unreachable)":"3, 3 (Port unerreichbar)","Other codes":"Andere Codes","0 net, 1 host, 4 too big":"0 Netz, 1 Host, 4 zu groß",Firewalls:"Firewalls","Often silent instead":"Oft stattdessen still","to port 9999":"an Port 9999","nothing listening there":"dort lauscht nichts","type 3 · code 3":"Typ 3 · Code 3","port unreachable":"Port unerreichbar","ICMP · Echo request":"ICMP · Echo-Anfrage",Code:"Code","Covers the whole ICMP message.":"Deckt die ganze ICMP-Nachricht ab.",Identifier:"Kennung","Matches replies to this ping program.":"Ordnet Antworten diesem Ping-Programm zu.","Windows counts up across every ping it sends.":"Windows zählt über alle gesendeten Pings hinweg hoch.","Windows ping’s filler: the alphabet, a to w, then again.":"Die Füllung von Windows-ping: das Alphabet von a bis w, dann wieder von vorn.","ICMP · Echo reply":"ICMP · Echo-Antwort","Sent back exactly as it came.":"Genau so zurückgeschickt, wie es kam.","ICMP · Time exceeded (TTL reached 0)":"ICMP · Zeit überschritten (TTL hat 0 erreicht)","Time exceeded (TTL reached 0)":"Zeit überschritten (TTL hat 0 erreicht)",Unused:"Ungenutzt","Original packet":"Ursprüngliches Paket","Its source, destination":"Seine Quelle, sein Ziel","its IP header and first 8 bytes (28 bytes)":"sein IP-Header und die ersten 8 Byte (28 Byte)","App data":"App-Daten","What the app sent; nothing on the server is listening for it.":"Was die App gesendet hat; auf dem Server wartet nichts darauf.","ICMP · Destination unreachable (port unreachable)":"ICMP · Ziel unerreichbar (Port unerreichbar)","Destination unreachable (port unreachable)":"Ziel unerreichbar (Port unerreichbar)","Sending Email":"E-Mail senden","SMTP command":"SMTP-Befehl","SMTP reply":"SMTP-Antwort","SMTP moves email: from your mail app to your provider’s server, and from that server to the recipient’s. It is a conversation of short text commands, each answered with a three-digit reply code. Reading mail is a different job, done with IMAP or POP3.":"SMTP befördert E-Mails: von deiner Mail-App zum Server deines Anbieters und von diesem Server zu dem des Empfängers. Es ist ein Gespräch aus kurzen Textbefehlen, die jeweils mit einem dreistelligen Antwortcode beantwortet werden. Mails lesen ist eine andere Aufgabe, erledigt mit IMAP oder POP3.","465/587 submit, 25 relay":"465/587 Einlieferung, 25 Weiterleitung","TCP, usually with TLS":"TCP, meist mit TLS",Commands:"Befehle",Replies:"Antworten","2xx ok, 3xx go on, 4/5xx error":"2xx ok, 3xx weiter, 4/5xx Fehler","Mail delivered":"Mail zugestellt","Two hops, one message":"Zwei Etappen, eine Nachricht","Alice’s app handed the message to her provider over an encrypted, logged-in connection. The provider found Bob’s mail server in DNS and relayed it there, upgrading that link to TLS. It now waits in Bob’s mailbox until he reads it with IMAP or POP3.":"Alices App hat die Nachricht über eine verschlüsselte, angemeldete Verbindung an ihren Anbieter übergeben. Der Anbieter fand Bobs Mailserver im DNS und leitete sie dorthin weiter, wobei er diese Verbindung auf TLS umstellte. Jetzt wartet sie in Bobs Postfach, bis er sie mit IMAP oder POP3 liest.","Laptop → provider → Bob’s":"Laptop → Anbieter → Bob",Submission:"Einlieferung","Port 465, TLS, login":"Port 465, TLS, Anmeldung",Relay:"Weiterleitung","Port 25, STARTTLS":"Port 25, STARTTLS","Checks at Bob’s":"Prüfungen bei Bob","Connect Securely":"Sicher verbinden","Alice presses Send. Her mail app connects to her provider’s submission server, smtp.example.com, on port 465. On this port TLS starts immediately, so the whole SMTP conversation, including her password, is encrypted.":"Alice klickt auf Senden. Ihre Mail-App verbindet sich mit dem Einlieferungsserver ihres Anbieters, smtp.example.com, auf Port 465. Auf diesem Port startet TLS sofort, also ist das ganze SMTP-Gespräch verschlüsselt, auch ihr Passwort.","TLS from the start":"TLS von Anfang an","SMTP inside TLS":"SMTP in TLS","Greeting & Login":"Begrüßung und Anmeldung","EHLO, then AUTH":"EHLO, dann AUTH","The server greets with code 220. The app says EHLO and the server lists what it supports, including AUTH. The app logs in with AUTH PLAIN (user name and password, base64-encoded) and gets 235: authenticated.":"Der Server grüßt mit Code 220. Die App sagt EHLO, und der Server listet auf, was er unterstützt, darunter AUTH. Die App meldet sich mit AUTH PLAIN an (Benutzername und Passwort, base64-codiert) und bekommt 235: angemeldet.",Greeting:"Begrüßung",Capabilities:"Fähigkeiten","Login result":"Anmeldeergebnis","user and password, base64":"Benutzer und Passwort, base64","Send the Message":"Die Nachricht senden","Envelope, then content":"Erst der Umschlag, dann der Inhalt","MAIL FROM and RCPT TO are the envelope: sender and recipient. PIPELINING lets all three commands share one packet. After 354 comes the message, ended by a line holding just a dot.":"MAIL FROM und RCPT TO sind der Umschlag: Absender und Empfänger. Mit PIPELINING teilen sich alle drei Befehle ein Paket. Nach 354 kommt die Nachricht, beendet durch eine Zeile, die nur einen Punkt enthält.",Envelope:"Umschlag","Content ends":"Inhalt endet","A line with only “.”":"Eine Zeile nur mit „.“",Result:"Ergebnis","… message …":"… Nachricht …","Find Bob’s Server":"Bobs Server finden","An MX lookup in DNS":"Eine MX-Abfrage im DNS","Alice’s provider now has to deliver to example.org. It asks DNS for that domain’s MX record, which names the server that accepts its mail, then looks up that server’s address.":"Alices Anbieter muss jetzt an example.org zustellen. Er fragt das DNS nach dem MX-Eintrag dieser Domain, der den Server nennt, der ihre Mails annimmt, und schlägt dann die Adresse dieses Servers nach.","MX record":"MX-Eintrag","Asked by":"Gefragt von","Alice’s provider":"Alices Anbieter","Server to Server":"Von Server zu Server","Port 25, upgraded with STARTTLS":"Port 25, mit STARTTLS abgesichert","The provider connects to mx.example.org on port 25. This conversation starts in plain text: the greeting and EHLO reply advertise STARTTLS, the provider asks for it, gets 220 and both sides switch to TLS.":"Der Anbieter verbindet sich mit mx.example.org auf Port 25. Dieses Gespräch beginnt im Klartext: Die Begrüßung und die EHLO-Antwort bieten STARTTLS an, der Anbieter fordert es an, bekommt 220, und beide Seiten wechseln zu TLS.","Starts as":"Beginnt als","Plain text":"Klartext",Upgrade:"Umstellung",Deliver:"Zustellen","The same transaction again":"Dieselbe Transaktion noch einmal","With TLS on, the provider repeats EHLO, then the envelope and the message, now with a DKIM signature and a Received header added. Bob’s server checks SPF, DKIM and DMARC and accepts it.":"Mit TLS wiederholt der Anbieter EHLO, dann den Umschlag und die Nachricht, jetzt mit einer DKIM-Signatur und einem zusätzlichen Received-Header. Bobs Server prüft SPF, DKIM und DMARC und nimmt sie an.","Login needed":"Anmeldung nötig","No (server to server)":"Nein (Server zu Server)","1,316 bytes (signed)":"1,316 Byte (signiert)","Server Hello + encrypted handshake, 2 segments":"Server Hello + verschlüsselter Handshake, 2 Segmente","250 capabilities (PIPELINING, SIZE, AUTH …)":"250 Fähigkeiten (PIPELINING, SIZE, AUTH …)","AUTH PLAIN (credentials)":"AUTH PLAIN (Zugangsdaten)","MAIL FROM, RCPT TO, DATA (pipelined)":"MAIL FROM, RCPT TO, DATA (per Pipelining)","Message (316 bytes), then “.”":"Nachricht (316 Byte), dann „.“","250 capabilities (PIPELINING, STARTTLS …)":"250 Fähigkeiten (PIPELINING, STARTTLS …)","250 capabilities (PIPELINING, SIZE …)":"250 Fähigkeiten (PIPELINING, SIZE …)","Message (1,316 bytes), then “.”":"Nachricht (1,316 Byte), dann „.“","What this client supports. Its exact contents vary from client to client; this is an example.":"Was dieser Client unterstützt. Der genaue Inhalt unterscheidet sich von Client zu Client; dies ist ein Beispiel.","up to 512 bytes":"bis zu 512 Byte","The server’s choices and its key share.":"Die Auswahl des Servers und sein Schlüsselanteil.","Encrypted Extensions, Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions, Certificate (die Kette), Certificate Verify (die Signatur), Finished","Alice’s message (316 bytes), then a line holding only “.”":"Alices Nachricht (316 Byte), dann eine Zeile, die nur „.“ enthält","example.org, type MX, class IN":"example.org, Typ MX, Klasse IN","mx.example.org, type A, class IN":"mx.example.org, Typ A, Klasse IN",Timestamps:"Zeitstempel","Used to measure round trips; both sides offered them.":"Dienen zum Messen der Umlaufzeiten; beide Seiten haben sie angeboten.","The signed message (1,316 bytes), then a line holding only “.”":"Die signierte Nachricht (1,316 Byte), dann eine Zeile, die nur „.“ enthält","Downloading Email":"E-Mails abholen","POP3 command":"POP3-Befehl","POP3 reply":"POP3-Antwort","Post Office Protocol, version 3":"Post Office Protocol, Version 3","POP3 lets a mail app download messages from a mailbox on a server. It was designed for one device that fetches mail and then removes it from the server. Commands are short words, and every reply starts with +OK or -ERR.":"Mit POP3 lädt eine Mail-App Nachrichten aus einem Postfach auf einem Server herunter. Es wurde für ein einzelnes Gerät entworfen, das Mails abholt und sie dann vom Server löscht. Befehle sind kurze Wörter, und jede Antwort beginnt mit +OK oder -ERR.",Model:"Modell","Download, then delete":"Herunterladen, dann löschen","Mail downloaded":"Mail heruntergeladen","And gone from the server":"Und vom Server verschwunden","Bob’s app logged in, saw two messages, downloaded the first and deleted it, which the server carried out at QUIT. That message now lives only on this laptop, which is why POP3 suits one device and IMAP suits several.":"Bobs App meldete sich an, sah zwei Nachrichten, lud die erste herunter und löschte sie, was der Server bei QUIT ausführte. Diese Nachricht gibt es jetzt nur noch auf diesem Laptop, deshalb passt POP3 zu einem Gerät und IMAP zu mehreren.","2 waiting, 1 downloaded":"2 wartend, 1 heruntergeladen",Deleted:"Gelöscht","At QUIT (UPDATE state)":"Bei QUIT (Zustand UPDATE)","Best for":"Am besten für","A single device":"Ein einzelnes Gerät","Bob’s mail app connects to pop.example.org on port 995, where TLS starts right away. Inside it, the server greets with +OK. (On port 110 the session starts in plain text and is upgraded with the STLS command.)":"Bobs Mail-App verbindet sich mit pop.example.org auf Port 995, wo TLS sofort startet. Darin grüßt der Server mit +OK. (Auf Port 110 beginnt die Sitzung im Klartext und wird mit dem Befehl STLS umgestellt.)","USER, then PASS":"USER, dann PASS","The app sends the user name with USER and the password with PASS. Each command gets its own +OK. Because the session is inside TLS, the password isn’t readable on the way.":"Die App sendet den Benutzernamen mit USER und das Passwort mit PASS. Jeder Befehl bekommt sein eigenes +OK. Weil die Sitzung in TLS läuft, ist das Passwort unterwegs nicht lesbar.","Protected by":"Geschützt durch","Check the Mailbox":"Das Postfach prüfen","STAT and LIST":"STAT und LIST","STAT returns the number of messages and their total size: 2 messages, 5120 bytes. LIST gives each message’s number and size, ending with a line holding just a dot.":"STAT liefert die Anzahl der Nachrichten und ihre Gesamtgröße: 2 Nachrichten, 5120 Byte. LIST nennt Nummer und Größe jeder Nachricht und endet mit einer Zeile, die nur einen Punkt enthält.","Message 1":"Nachricht 1","Message 2":"Nachricht 2",Download:"Herunterladen","RETR 1 asks for the first message. The server answers +OK with its size, then the message and a closing dot: 1904 bytes plus the reply line, two TCP segments.":"RETR 1 fordert die erste Nachricht an. Der Server antwortet mit +OK und ihrer Größe, dann folgen die Nachricht und ein abschließender Punkt: 1904 Byte plus die Antwortzeile, zwei TCP-Segmente.",Command:"Befehl","Delete & Quit":"Löschen und beenden","Deleted only at QUIT":"Erst bei QUIT gelöscht","DELE 1 only marks the message. The server removes it when the app says QUIT: if the connection dropped before that, nothing would be deleted. Many apps offer “leave a copy on the server”, which skips DELE.":"DELE 1 markiert die Nachricht nur. Der Server entfernt sie, wenn die App QUIT sagt: Bräche die Verbindung vorher ab, würde nichts gelöscht. Viele Apps bieten „Kopie auf dem Server lassen“ an, das überspringt DELE.","Marks message 1":"Markiert Nachricht 1",Removed:"Entfernt",Option:"Option","Leave a copy on server":"Kopie auf dem Server lassen","PASS (password)":"PASS (Passwort)","+OK 1904 octets, message, “.” (2 segments)":"+OK 1904 octets, Nachricht, „.“ (2 Segmente)","+OK 1904 octets, the 1,904-byte message, then a line holding only “.”":"+OK 1904 octets, die 1,904 Byte lange Nachricht, dann eine Zeile, die nur „.“ enthält","Mail That Stays in Sync":"Mails, die synchron bleiben","IMAP command":"IMAP-Befehl","IMAP response":"IMAP-Antwort","Internet Message Access Protocol":"Protokoll für den Internet-Nachrichtenzugriff","IMAP lets mail apps work with a mailbox that stays on the server. Folders, read and flagged marks and deletions are kept there, so a phone, a laptop and webmail all see the same mailbox. The server can also tell an app about new mail as it arrives.":"Mit IMAP arbeiten Mail-Apps mit einem Postfach, das auf dem Server bleibt. Ordner, Gelesen- und Markiert-Kennzeichen und Löschungen werden dort gespeichert, sodass Handy, Laptop und Webmail dasselbe Postfach sehen. Der Server kann eine App außerdem über neue Mails informieren, sobald sie eintreffen.","Mail stays on the server":"Mails bleiben auf dem Server",Syncs:"Synchronisiert","Folders and flags":"Ordner und Flags","Mailbox in sync":"Postfach synchron","Read once, read everywhere":"Einmal gelesen, überall gelesen","Bob’s app opened his inbox, read a message, which marked it \\Seen on the server for all his devices, and then waited with IDLE until the server announced new mail. Nothing was deleted: the server still holds everything.":"Bobs App öffnete seinen Posteingang und las eine Nachricht, was sie auf dem Server für alle seine Geräte als \\Seen markierte, und wartete dann mit IDLE, bis der Server neue Mail meldete. Nichts wurde gelöscht: Der Server hat noch alles.","2, then 3 (new mail)":"2, dann 3 (neue Mail)","Read mark":"Gelesen-Markierung","\\Seen, stored on server":"\\Seen, auf dem Server gespeichert","New mail":"Neue Mail","Pushed during IDLE":"Während IDLE zugestellt","Bob’s app connects to imap.example.org on port 993, where TLS starts right away. The server greets with an untagged “* OK” line that also lists its capabilities, such as IDLE.":"Bobs App verbindet sich mit imap.example.org auf Port 993, wo TLS sofort startet. Der Server grüßt mit einer ungetaggten „* OK“-Zeile, die auch seine Fähigkeiten auflistet, etwa IDLE.","Commands carry tags":"Befehle tragen Tags","Every command starts with a tag the app chooses, like a1, and the server ends its answer with the same tag. That way several commands can be in flight and each reply is matched up. Lines starting with * are untagged data.":"Jeder Befehl beginnt mit einem Tag, den die App wählt, etwa a1, und der Server beendet seine Antwort mit demselben Tag. So können mehrere Befehle gleichzeitig unterwegs sein, und jede Antwort wird richtig zugeordnet. Zeilen, die mit * beginnen, sind ungetaggte Daten.",Tags:"Tags","Match replies to commands":"Ordnen Antworten Befehlen zu","Open the Inbox":"Den Posteingang öffnen","SELECT a folder":"Einen Ordner mit SELECT öffnen","SELECT INBOX opens the folder. The server reports the message count, the flags it supports and the first unread message, then confirms the folder is open read-write.":"SELECT INBOX öffnet den Ordner. Der Server meldet die Anzahl der Nachrichten, die unterstützten Flags und die erste ungelesene Nachricht und bestätigt dann, dass der Ordner mit Lese- und Schreibzugriff geöffnet ist.","First unread":"Erste ungelesene",Access:"Zugriff","Read a Message":"Eine Nachricht lesen","FETCH, and the \\Seen flag":"FETCH und das \\Seen-Flag","FETCH 2 BODY[] downloads message 2 (three TCP segments). That sets its \\Seen flag on the server, so it shows as read on Bob’s phone too, and the message stays there.":"FETCH 2 BODY[] lädt Nachricht 2 herunter (drei TCP-Segmente). Das setzt ihr \\Seen-Flag auf dem Server, sodass sie auch auf Bobs Handy als gelesen erscheint, und die Nachricht bleibt dort.","Flag set":"Flag gesetzt","\\Seen (on the server)":"\\Seen (auf dem Server)","Wait for New Mail":"Auf neue Mail warten","IDLE: the server pushes":"IDLE: Der Server meldet sich","IDLE tells the server “let me know when something changes”. About 42 seconds later Alice’s message arrives and the server pushes “* 3 EXISTS” straight away. The app ends IDLE with DONE and can fetch the new mail.":"IDLE sagt dem Server: „Sag Bescheid, wenn sich etwas ändert.“ Etwa 42 Sekunden später trifft Alices Nachricht ein, und der Server schickt sofort „* 3 EXISTS“. Die App beendet IDLE mit DONE und kann die neue Mail abrufen.","Server says":"Server meldet","* 3 EXISTS (new mail)":"* 3 EXISTS (neue Mail)","Ended by":"Beendet durch","a1 LOGIN (user and password)":"a1 LOGIN (Benutzer und Passwort)","* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, the 3,216-byte message, then a3 OK FETCH completed":"* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, die 3,216 Byte lange Nachricht, dann a3 OK FETCH completed","Transferring Files":"Dateien übertragen","FTP command":"FTP-Befehl","FTP reply":"FTP-Antwort","File data":"Dateidaten","FTP moves files between a client and a server. It is unusual in using two TCP connections: one for commands and replies, and a fresh one for each file or listing. It dates from the early 1970s and sends everything, passwords included, as plain text.":"FTP überträgt Dateien zwischen einem Client und einem Server. Ungewöhnlich ist, dass es zwei TCP-Verbindungen nutzt: eine für Befehle und Antworten und für jede Datei oder Auflistung eine neue. Es stammt aus den frühen 1970ern und sendet alles im Klartext, auch Passwörter.","21 control, data varies":"21 Steuerung, Daten variabel",Connections:"Verbindungen","Control + one per transfer":"Steuerung + eine pro Übertragung",Encryption:"Verschlüsselung","None (plain text)":"Keine (Klartext)","Safer options":"Sicherere Alternativen","File downloaded":"Datei heruntergeladen","Two connections, no encryption":"Zwei Verbindungen, keine Verschlüsselung","Commands went over the control connection, the file over its own data connection, and closing that connection marked the end of the file. Anyone on the path could have read the password and the file, which is why SFTP or FTPS is used today.":"Die Befehle liefen über die Steuerverbindung, die Datei über ihre eigene Datenverbindung, und das Schließen dieser Verbindung markierte das Dateiende. Jeder auf dem Weg hätte Passwort und Datei lesen können, deshalb nutzt man heute SFTP oder FTPS.","2 (control + data)":"2 (Steuerung + Daten)",File:"Datei","4,000 bytes, 3 segments":"4,000 Byte, 3 Segmente",Password:"Passwort","Sent in plain text":"Im Klartext gesendet","Use instead":"Stattdessen nutzen","Control Connection":"Steuerverbindung","Port 21, plain text":"Port 21, Klartext","The FTP app opens a TCP connection to ftp.example.com on port 21. This control connection carries commands and replies for the whole session. The server greets with 220. Like SMTP, every reply starts with a three-digit code.":"Die FTP-App öffnet eine TCP-Verbindung zu ftp.example.com auf Port 21. Diese Steuerverbindung trägt Befehle und Antworten der ganzen Sitzung. Der Server grüßt mit 220. Wie bei SMTP beginnt jede Antwort mit einem dreistelligen Code.","USER and PASS, readable by anyone":"USER und PASS, für jeden lesbar","The app sends USER, the server asks for the password with 331, and PASS sends it. Nothing is encrypted, so the user name and password cross every network on the way as readable text.":"Die App sendet USER, der Server fragt mit 331 nach dem Passwort, und PASS sendet es. Nichts ist verschlüsselt, also überqueren Benutzername und Passwort jedes Netz auf dem Weg als lesbarer Text.","Visible to":"Sichtbar für","Anyone on the path":"Jeden auf dem Weg","Passive Mode":"Passiver Modus","The server names a data port":"Der Server nennt einen Datenport","TYPE I asks for a byte-for-byte binary copy. PASV asks the server to open a port for the data connection. The reply encodes the address and port as six numbers: 195 × 256 + 149 = port 50069. The laptop connects out, which works through NAT.":"TYPE I fordert eine bytegenaue Binärkopie an. PASV bittet den Server, einen Port für die Datenverbindung zu öffnen. Die Antwort codiert Adresse und Port als sechs Zahlen: 195 × 256 + 149 = Port 50069. Der Laptop verbindet sich nach außen, was durch NAT hindurch funktioniert.","Data port":"Datenport","Active mode":"Aktiver Modus","Server dials in: NAT blocks":"Server wählt sich ein: NAT blockiert","Data Connection":"Datenverbindung","A second TCP connection":"Eine zweite TCP-Verbindung","The app opens a second TCP connection, to port 50069, and asks for the file on the control connection with RETR. The server answers 150 there and starts sending the file over the new connection.":"Die App öffnet eine zweite TCP-Verbindung, zu Port 50069, und fordert die Datei auf der Steuerverbindung mit RETR an. Der Server antwortet dort mit 150 und beginnt, die Datei über die neue Verbindung zu senden.","Data to":"Daten an","The File Arrives":"Die Datei kommt an","Closing the connection ends it":"Das Schließen der Verbindung beendet sie","The 4,000 bytes arrive in 3 TCP segments. FTP sends no length marker in the data itself: the server closes the data connection to mark the end of the file. Once the laptop has acknowledged everything, the server confirms with 226 on the control connection.":"Die 4,000 Byte kommen in 3 TCP-Segmenten an. FTP sendet in den Daten selbst keine Längenangabe: Der Server schließt die Datenverbindung, um das Dateiende zu markieren. Sobald der Laptop alles bestätigt hat, bestätigt der Server mit 226 auf der Steuerverbindung.","End of file":"Dateiende","Data connection closed":"Datenverbindung geschlossen","4,000 bytes, readable by anyone":"4,000 Byte, für jeden lesbar","end of file:":"Dateiende:","data connection closed":"Datenverbindung geschlossen",Quit:"Beenden","Close the control connection":"Die Steuerverbindung schließen","QUIT ends the session and the server says goodbye with 221. For anything sensitive, SFTP (a different protocol, run over SSH) or FTPS (FTP inside TLS) gives the same job encryption.":"QUIT beendet die Sitzung, und der Server verabschiedet sich mit 221. Für alles Vertrauliche erledigen SFTP (ein anderes Protokoll, das über SSH läuft) oder FTPS (FTP in TLS) dieselbe Aufgabe mit Verschlüsselung.","Encrypted cousins":"Verschlüsselte Verwandte","FTP data":"FTP-Daten","The file itself, unencrypted: anyone on the path could read it.":"Die Datei selbst, unverschlüsselt: Jeder auf dem Weg könnte sie lesen.","Secure Remote Login":"Sichere Fernanmeldung","Plain setup":"Aufbau im Klartext","From laptop":"Vom Laptop","From server":"Vom Server","Some packets not shown":"Einige Pakete nicht gezeigt","SSH gives you an encrypted, authenticated connection to another computer, to run commands on it, copy files (SFTP, scp) or carry other connections. The server proves who it is with a host key; you prove who you are with a key pair or a password.":"SSH gibt dir eine verschlüsselte, authentifizierte Verbindung zu einem anderen Computer, um dort Befehle auszuführen, Dateien zu kopieren (SFTP, scp) oder andere Verbindungen zu tragen. Der Server beweist mit einem Host-Schlüssel, wer er ist; du beweist es mit einem Schlüsselpaar oder einem Passwort.","Server proves":"Server beweist","Host key (known_hosts)":"Host-Schlüssel (known_hosts)","You prove":"Du beweist","Key pair or password":"Schlüsselpaar oder Passwort","Logged in securely":"Sicher angemeldet","Encrypted from the key exchange on":"Verschlüsselt ab dem Schlüsselaustausch","The two sides agreed on algorithms, built shared keys with a post-quantum hybrid exchange, and the server proved its identity with its host key. Alice proved hers by signing with a private key that never left the laptop, then typed a command, one packet per key.":"Beide Seiten einigten sich auf Algorithmen, erzeugten gemeinsame Schlüssel mit einem hybriden Post-Quanten-Austausch, und der Server bewies seine Identität mit seinem Host-Schlüssel. Alice bewies ihre, indem sie mit einem privaten Schlüssel signierte, der den Laptop nie verließ, und tippte dann einen Befehl, ein Paket pro Taste.",Login:"Anmeldung","Ed25519 key, no password":"Ed25519-Schlüssel, kein Passwort","Say Hello":"Hallo sagen","Versions, in plain text":"Versionen, im Klartext","Alice runs “ssh alice@server.example.com”. After the TCP handshake on port 22, each side sends one line of plain text naming the SSH protocol version (2.0) and its software. Everything else in SSH is binary.":"Alice führt „ssh alice@server.example.com“ aus. Nach dem TCP-Handshake auf Port 22 schickt jede Seite eine Zeile Klartext mit der Version des SSH-Protokolls (2.0) und ihrer Software. Alles andere in SSH ist binär.","Agree on Algorithms":"Algorithmen vereinbaren","KEXINIT lists, first match wins":"KEXINIT-Listen, der erste Treffer gewinnt","Each side sends a KEXINIT listing every algorithm it supports, in order of preference, for key exchange, host keys, encryption, integrity and compression. In each category the first algorithm on the laptop’s list that the server also supports is chosen.":"Jede Seite schickt ein KEXINIT mit allen Algorithmen, die sie unterstützt, nach Vorliebe geordnet: für Schlüsselaustausch, Host-Schlüssel, Verschlüsselung, Integrität und Kompression. In jeder Kategorie wird der erste Algorithmus auf der Liste des Laptops gewählt, den auch der Server unterstützt.","Host key":"Host-Schlüssel","server’s algorithm lists":"Algorithmuslisten des Servers","in order of preference":"nach Vorliebe geordnet","laptop’s algorithm lists":"Algorithmuslisten des Laptops","Key Exchange":"Schlüsselaustausch","Shared keys, and a host key check":"Gemeinsame Schlüssel und eine Prüfung des Host-Schlüssels","The laptop sends its half of a hybrid exchange: a Streamlined NTRU Prime key, chosen to resist future quantum computers, plus an X25519 key. The server answers with its half, its host key and a signature over the exchange. NEWKEYS switches encryption on.":"Der Laptop schickt seine Hälfte eines hybriden Austauschs: einen Streamlined-NTRU-Prime-Schlüssel, gewählt, um künftigen Quantencomputern standzuhalten, dazu einen X25519-Schlüssel. Der Server antwortet mit seiner Hälfte, seinem Host-Schlüssel und einer Signatur über den Austausch. NEWKEYS schaltet die Verschlüsselung ein.",Hybrid:"Hybrid","Matches known_hosts":"Stimmt mit known_hosts überein","First visit":"Erster Besuch","ssh asks you to confirm":"ssh bittet dich um Bestätigung","public keys":"öffentliche Schlüssel","its half, its host key":"seine Hälfte, sein Host-Schlüssel","and a signature":"und eine Signatur","Log In with a Key":"Per Schlüssel anmelden","Sign, don’t send a secret":"Signieren statt ein Geheimnis senden","The server lists the login methods it accepts. The laptop offers Alice’s public key, and the server says it would accept it. The laptop then signs this session with the private key, which never leaves the laptop. The server checks the signature against authorized_keys.":"Der Server listet die Anmeldemethoden auf, die er akzeptiert. Der Laptop bietet Alices öffentlichen Schlüssel an, und der Server sagt, dass er ihn akzeptieren würde. Dann signiert der Laptop diese Sitzung mit dem privaten Schlüssel, der den Laptop nie verlässt. Der Server prüft die Signatur anhand von authorized_keys.",Methods:"Methoden","Ed25519, private stays here":"Ed25519, der private bleibt hier","Checked with":"Geprüft mit","alice’s public key":"Alices öffentlicher Schlüssel","would you accept it?":"würdest du ihn akzeptieren?","yes, that key":"ja, dieser Schlüssel","is in authorized_keys":"steht in authorized_keys","same key, plus a signature":"derselbe Schlüssel, plus Signatur","made with the private key":"mit dem privaten Schlüssel erstellt","logged in":"angemeldet","Open a Session":"Eine Sitzung öffnen","Channels inside one connection":"Kanäle in einer Verbindung","One SSH connection can carry many channels: a shell, file transfers, forwarded ports. The laptop opens a session channel, then asks for a terminal and a shell (not shown), and the server sends its welcome text and a prompt.":"Eine SSH-Verbindung kann viele Kanäle tragen: eine Shell, Dateiübertragungen, weitergeleitete Ports. Der Laptop öffnet einen Sitzungskanal, bittet dann um ein Terminal und eine Shell (nicht gezeigt), und der Server schickt seinen Begrüßungstext und einen Prompt.",Channel:"Kanal",session:"Sitzung","Then asks for":"Fordert dann an","A terminal and a shell":"Ein Terminal und eine Shell","Also possible":"Ebenfalls möglich","SFTP, port forwarding":"SFTP, Portweiterleitung","open a channel:":"Kanal öffnen:","channel open":"Kanal offen","Type a Command":"Einen Befehl tippen","Every key is a packet":"Jede Taste ist ein Paket","Alice types pwd. Each key goes out at once in its own encrypted packet, and the server sends the character back to be shown (the echo). Since 9.5, OpenSSH sends keys on a 20 ms beat and adds decoy packets, so typing rhythm is harder to read from the timing.":"Alice tippt pwd. Jede Taste geht sofort in einem eigenen verschlüsselten Paket hinaus, und der Server schickt das Zeichen zur Anzeige zurück (das Echo). Seit Version 9.5 sendet OpenSSH Tasten in einem 20-ms-Takt und fügt Täuschpakete hinzu, damit sich der Tipprhythmus schwerer aus dem Timing ablesen lässt.","Per key":"Pro Taste","1 packet, 90 bytes":"1 Paket, 90 Byte",Echo:"Echo","Sent back by the server":"Vom Server zurückgeschickt",Timing:"Timing","20 ms beat plus decoys":"20-ms-Takt plus Täuschpakete","Enter key":"Eingabetaste","Client: KEX_ECDH_INIT (sntrup761x25519 public keys)":"Client: KEX_ECDH_INIT (öffentliche Schlüssel sntrup761x25519)","Server: KEX_ECDH_REPLY (host key, its half, signature)":"Server: KEX_ECDH_REPLY (Host-Schlüssel, seine Hälfte, Signatur)","Encrypted (len=44): service request, ssh-userauth":"Verschlüsselt (len=44): Dienstanfrage, ssh-userauth","Encrypted (len=44): service accept":"Verschlüsselt (len=44): Dienst angenommen","Encrypted (len=68): login with method none":"Verschlüsselt (len=68): Anmeldung mit Methode none","Encrypted (len=52): try publickey,password":"Verschlüsselt (len=52): versuche publickey,password","Encrypted (len=140): offer public key":"Verschlüsselt (len=140): bietet öffentlichen Schlüssel an","Encrypted (len=100): public key OK":"Verschlüsselt (len=100): öffentlicher Schlüssel OK","Encrypted (len=308): public key + signature":"Verschlüsselt (len=308): öffentlicher Schlüssel + Signatur","Encrypted (len=28): login success":"Verschlüsselt (len=28): Anmeldung erfolgreich","Encrypted (len=52): channel open: session":"Verschlüsselt (len=52): Kanal öffnen: session","Encrypted (len=44): channel open confirmed":"Verschlüsselt (len=44): Kanalöffnung bestätigt","Encrypted (len=36): keystroke":"Verschlüsselt (len=36): Tastendruck","Encrypted (len=36): echo":"Verschlüsselt (len=36): Echo","Encrypted (len=36): keystroke (Enter)":"Verschlüsselt (len=36): Tastendruck (Enter)","Encrypted (len=132): output and a new prompt":"Verschlüsselt (len=132): Ausgabe und ein neuer Prompt","Packet length":"Paketlänge","Bytes after this field.":"Bytes nach diesem Feld.","Padding length":"Padding-Länge","Random padding brings the packet to a multiple of 8 bytes.":"Zufälliges Padding bringt das Paket auf ein Vielfaches von 8 Byte.",Cookie:"Cookie","Host keys":"Host-Schlüssel","Ciphers, out":"Chiffren, ausgehend","Ciphers, in":"Chiffren, eingehend","MACs, out":"MACs, ausgehend","Compression, out":"Kompression, ausgehend","Compression, in":"Kompression, eingehend","Languages, out":"Sprachen, ausgehend","Languages, in":"Sprachen, eingehend","First packet follows":"Erstes Paket folgt",Reserved:"Reserviert","Public keys":"Öffentliche Schlüssel","51 bytes: ssh-ed25519 public key":"51 Byte: öffentlicher ssh-ed25519-Schlüssel","Server’s half":"Hälfte des Servers","1071 bytes (sntrup761 ciphertext 1,039 + X25519 32)":"1071 Byte (sntrup761-Chiffretext 1,039 + X25519 32)",Signature:"Signatur","83 bytes: ssh-ed25519 signature over the exchange":"83 Byte: ssh-ed25519-Signatur über den Austausch","From the next packet on, this side encrypts.":"Ab dem nächsten Paket verschlüsselt diese Seite.","SSH · encrypted packet":"SSH · verschlüsseltes Paket","Encrypted packet":"Verschlüsseltes Paket","With chacha20-poly1305 even the length is encrypted; a 16-byte tag at the end shows any change.":"Mit chacha20-poly1305 ist sogar die Länge verschlüsselt; ein 16 Byte langes Tag am Ende zeigt jede Änderung.","SSH_MSG_USERAUTH_REQUEST (50): user “alice”, service “ssh-connection”, method “none”":"SSH_MSG_USERAUTH_REQUEST (50): Benutzer „alice“, Dienst „ssh-connection“, Methode „none“","SSH_MSG_USERAUTH_FAILURE (51): methods that can continue: “publickey,password”":"SSH_MSG_USERAUTH_FAILURE (51): Methoden, mit denen es weitergeht: „publickey,password“","SSH_MSG_USERAUTH_REQUEST (50): method “publickey”, no signature, the ssh-ed25519 public key":"SSH_MSG_USERAUTH_REQUEST (50): Methode „publickey“, ohne Signatur, der öffentliche ssh-ed25519-Schlüssel","SSH_MSG_USERAUTH_PK_OK (60): the same ssh-ed25519 key":"SSH_MSG_USERAUTH_PK_OK (60): derselbe ssh-ed25519-Schlüssel","SSH_MSG_USERAUTH_REQUEST (50): method “publickey-hostbound-v00@openssh.com”, the key, the server’s host key and a signature":"SSH_MSG_USERAUTH_REQUEST (50): Methode „publickey-hostbound-v00@openssh.com“, der Schlüssel, der Host-Schlüssel des Servers und eine Signatur","SSH_MSG_CHANNEL_OPEN (90): “session”, channel 0, window 2 MB, packets up to 32 KB":"SSH_MSG_CHANNEL_OPEN (90): „session“, Kanal 0, Fenster 2 MB, Pakete bis 32 KB","SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): channel 0 is open":"SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): Kanal 0 ist offen","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”":"SSH_MSG_CHANNEL_DATA (94), Kanal 0: 1 Byte, „p“","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), Kanal 0: 1 Byte, „p“, zur Anzeige zurückgeschickt","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”":"SSH_MSG_CHANNEL_DATA (94), Kanal 0: 1 Byte, „w“","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), Kanal 0: 1 Byte, „w“, zur Anzeige zurückgeschickt","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”":"SSH_MSG_CHANNEL_DATA (94), Kanal 0: 1 Byte, „d“","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), Kanal 0: 1 Byte, „d“, zur Anzeige zurückgeschickt","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, a carriage return (Enter)":"SSH_MSG_CHANNEL_DATA (94), Kanal 0: 1 Byte, ein Wagenrücklauf (Enter)","SSH_MSG_CHANNEL_DATA (94), channel 0: 94 bytes: a new line, the shell’s terminal codes, “/home/alice”, and the coloured prompt":"SSH_MSG_CHANNEL_DATA (94), Kanal 0: 94 Byte: ein Zeilenumbruch, die Terminalcodes der Shell, „/home/alice“ und der farbige Prompt","Encryption Explained":"Verschlüsselung erklärt","From browser":"Vom Browser","TLS puts a secure channel on top of TCP. It proves the server’s identity with a certificate, agrees on fresh keys, then encrypts and authenticates everything sent. HTTPS, secure email and many other protocols run inside it. SSL was the name of its predecessor.":"TLS legt einen sicheren Kanal über TCP. Es beweist die Identität des Servers mit einem Zertifikat, vereinbart frische Schlüssel und verschlüsselt und authentifiziert dann alles Gesendete. HTTPS, sichere E-Mail und viele andere Protokolle laufen darin. SSL hieß sein Vorgänger.",Sits:"Liegt","Between TCP and the app":"Zwischen TCP und der App","OSI layer":"OSI-Schicht","Often placed at 6":"Oft bei 6 eingeordnet",Current:"Aktuell",Retired:"Ausgemustert","SSL 2 and 3, TLS 1.0 and 1.1":"SSL 2 und 3, TLS 1.0 und 1.1","The app’s own (443, 993 …)":"Der der App (443, 993 …)","Secure from start to finish":"Von Anfang bis Ende sicher","One round trip to set up":"Ein Umlauf für den Aufbau","One round trip agreed on a version, a cipher and a post-quantum hybrid key. The certificate chain proved who the server was, and every byte after the Server Hello was encrypted and authenticated, right up to the close_notify. Press REPLAY to watch it again.":"Ein einziger Umlauf genügte, um Version, Chiffre und einen hybriden Post-Quanten-Schlüssel zu vereinbaren. Die Zertifikatskette bewies, wer der Server war, und jedes Byte nach dem Server Hello war verschlüsselt und authentifiziert, bis zum close_notify. Drücke NOCHMAL, um es dir noch einmal anzusehen.","1 round trip":"1 Umlauf","Everything the browser supports":"Alles, was der Browser unterstützt","After the TCP handshake the browser lists what it can do: TLS versions, cipher suites, and key shares for the groups it expects, including the post-quantum hybrid X25519MLKEM768. It also names the site (SNI) and the protocols it speaks (ALPN).":"Nach dem TCP-Handshake listet der Browser auf, was er kann: TLS-Versionen, Cipher Suites und Schlüsselanteile für die Gruppen, die er erwartet, darunter das hybride Post-Quanten-Verfahren X25519MLKEM768. Außerdem nennt er die Website (SNI) und die Protokolle, die er spricht (ALPN).",Versions:"Versionen","versions, ciphers, key shares":"Versionen, Chiffren, Schlüsselanteile","Choices made, keys computed":"Auswahl getroffen, Schlüssel berechnet","The server picks TLS 1.3, the cipher suite and the hybrid group, and sends its own key share. From the two shares both sides compute the same secret without it ever crossing the network. Everything after this message is encrypted.":"Der Server wählt TLS 1.3, die Cipher Suite und die hybride Gruppe und schickt seinen eigenen Schlüsselanteil. Aus den beiden Anteilen berechnen beide Seiten dasselbe Geheimnis, ohne dass es je das Netz überquert. Alles nach dieser Nachricht ist verschlüsselt.",Group:"Gruppe","From here on":"Ab hier","its key share":"sein Schlüsselanteil",Certificate:"Zertifikat","Who the server is, proven":"Wer der Server ist, bewiesen","Now encrypted, the flight continues: the chosen protocol (http/1.1), the certificate chain, a signature made with the certificate’s private key, and Finished.":"Jetzt verschlüsselt geht es weiter: das gewählte Protokoll (http/1.1), die Zertifikatskette, eine mit dem privaten Schlüssel des Zertifikats erstellte Signatur und Finished.",Chain:"Kette","Site → intermediate → root":"Website → Zwischenzertifikat → Root","Proves the private key":"Beweist den privaten Schlüssel",Checked:"Geprüft","Name, dates, trusted root":"Name, Daten, vertrauenswürdige Root","encrypted: http/1.1, certificates,":"verschlüsselt: http/1.1, Zertifikate,","signature, Finished":"Signatur, Finished","One round trip, then data":"Ein Umlauf, dann Daten","The browser sends its own Finished: a check value over everything both sides said, keyed with the new secret, so any tampering with the hellos would show. TLS 1.3 needs one round trip before data flows; TLS 1.2 needed two.":"Der Browser schickt sein eigenes Finished: einen Prüfwert über alles, was beide Seiten gesagt haben, berechnet mit dem neuen Geheimnis, sodass jede Manipulation an den Hellos auffallen würde. TLS 1.3 braucht einen Umlauf, bevor Daten fließen; TLS 1.2 brauchte zwei.",Covers:"Deckt ab","The whole handshake":"Den ganzen Handshake","For old middleboxes":"Für alte Middleboxes","check value over":"Prüfwert über","the whole handshake":"den ganzen Handshake","Encrypted Data":"Verschlüsselte Daten","Records, tags and tickets":"Records, Tags und Tickets","HTTP now travels in encrypted records, each with a 16-byte tag that exposes any change. The server also sends two session tickets: next time the browser can resume with one and skip the certificate.":"HTTP reist jetzt in verschlüsselten Records, jeder mit einem 16 Byte langen Tag, das jede Änderung aufdeckt. Der Server schickt außerdem zwei Sitzungstickets: Beim nächsten Mal kann der Browser mit einem davon fortsetzen und das Zertifikat überspringen.","Per record":"Pro Record","22 bytes of overhead":"22 Byte Overhead","2, for resuming later":"2, zum späteren Fortsetzen",Visible:"Sichtbar","IPs, SNI, sizes, timing":"IPs, SNI, Größen, Timing","2 session tickets":"2 Sitzungstickets","for resuming later":"zum späteren Fortsetzen",Closing:"Schließen","close_notify, then TCP":"close_notify, dann TCP","After 75 idle seconds the server closes the connection. It first sends a close_notify alert, encrypted like everything else, so the browser knows the data ended on purpose and wasn’t cut short by an attacker. Then TCP closes as usual.":"Nach 75 Sekunden ohne Aktivität schließt der Server die Verbindung. Zuerst schickt er eine close_notify-Warnung, verschlüsselt wie alles andere, damit der Browser weiß, dass die Daten absichtlich endeten und nicht von einem Angreifer abgeschnitten wurden. Dann schließt TCP wie gewohnt.",Alert:"Warnung","Shows nothing was cut off":"Zeigt, dass nichts abgeschnitten wurde","TCP FIN from both sides":"TCP-FIN von beiden Seiten","alert: close_notify":"Warnung: close_notify",encrypted:"verschlüsselt","Server Hello, Change Cipher Spec (+ encrypted)":"Server Hello, Change Cipher Spec (+ verschlüsselt)","Encrypted handshake (continued)":"Verschlüsselter Handshake (Fortsetzung)","Encrypted handshake (certificate, verify, Finished)":"Verschlüsselter Handshake (Zertifikat, Verify, Finished)","Application Data (inside: close_notify alert)":"Application Data (darin: close_notify-Warnung)","Alert: close_notify (the data ends here, on purpose)":"Warnung: close_notify (die Daten enden hier, absichtlich)","No IP address":"Keine IP-Adresse","192.168.1.1 · DHCP server":"192.168.1.1 · DHCP-Server"},r=t=>`${t} ${t==="1"?"Record":"Records"}`,h={strings:{...o,...a},patterns:[[/^([\d,]+) bytes$/,"$1 Byte"],[/^(Ethernet II|IPv4|UDP|TCP) · (\d+) bytes$/,"$1 · $2 Byte"],[/^(Application Data|Handshake|Change Cipher Spec), ([\d,]+) bytes?$/,"$1, $2 Byte"],[/^([\d,]+) bytes: report\.pdf, bytes (.+)$/,"$1 Byte: report.pdf, Byte $2"],[/^(.+) h later$/,"$1 h später"],[/^(.+) min later$/,"$1 min später"],[/^(.+) s later$/,"$1 s später"],[/^(\S+) \(relative\)$/,"$1 (relativ)"],[/^(\d+) \(ephemeral\)$/,"$1 (kurzlebig)"],[/^(\d+) TCP segments$/,"$1 TCP-Segmente"],[/^(\d+) segments$/,"$1 Segmente"],[/^(.*), (\d+) segments$/,"$1, $2 Segmente"],[/^TLS 1\.3 · (\d+) records? · bytes (.+) of (.+)$/,(t,e,n,s)=>`TLS 1.3 · ${r(e)} · Byte ${n} von ${s}`],[/^TLS 1\.3 · (\d+) records?$/,(t,e)=>`TLS 1.3 · ${r(e)}`],[/^Ethernet padding · (\d+) bytes$/,"Ethernet-Padding · $1 Byte"],[/^(\d+) zero bytes, up to the 300-byte minimum$/,"$1 Null-Bytes, bis zum Minimum von 300 Byte"],[/^(\d+) zero bytes$/,"$1 Null-Bytes"],[/^(\d+) random bytes$/,"$1 Zufallsbytes"],[/^Seen as it leaves (.+)$/,"Gesehen beim Verlassen von $1"],[/^Option (\d+)$/,"Option $1"],[/^value (\d+), echo (\d+)$/,"Wert $1, Echo $2"],[/^20 bytes, plus (\d+) of options\.$/,"20 Byte, plus $1 Byte Optionen."],[/^Windows starts at (\d+)\. Set to (\d+) on purpose here\.$/,"Windows beginnt bei $1. Hier absichtlich auf $2 gesetzt."],[/^Started at (\d+); (\d+) routers? on the way each took 1\.$/,(t,e,n)=>n==="1"?`Begann bei ${e}; der Router auf dem Weg zog 1 ab.`:`Begann bei ${e}; jeder der ${n} Router auf dem Weg zog 1 ab.`],[/^all (\d+) bytes of it$/,"alle $1 Byte davon"],[/^The packet that caused this, as the reporting device received it \(TTL (\d+)\), so the sender can tell which packet it was\.$/,"Das Paket, das dies ausgelöst hat, so wie das meldende Gerät es empfangen hat (TTL $1), damit der Absender weiß, um welches Paket es ging."],[/^Port (\d+), TLS from the start$/,"Port $1, TLS von Anfang an"],[/^(\d+), TLS from the start$/,"$1, TLS von Anfang an"]],post:i};export{h as default};
